-- Owner-authorized editorial reinforcement of four existing seven-language groups.
DO $refuerzo$
DECLARE payload jsonb := $payload$[{"id":"900a29cc-a46f-4dc4-bd44-6515cbab06f4","language":"de","public_path":"/de/creep-stroganoff","recipe_group_id":"6ebd3387-890e-47d2-a9a2-4fabdcc46bb2","expected_updated_at":"2026-10-21T13:48:02.819322+00:00","after":{"excerpt":"Crêpes mit Rindfleisch, Champignons und cremiger Sauce. Für 4 Personen, etwa 90 Minuten einschließlich 30 Minuten Teigruhe.","summary":"Diese hausgemachten Stroganoff-Crêpes bestehen aus dünnem Mehl-Milch-Eier-Teig und einer Füllung aus Rindfleisch, Champignons und cremiger Sauce. Das Rezept ergibt 4 Portionen und ist kein Nachbau eines Restaurantketten-Rezepts.\n\nDas Wasser der Pilze vor der Brühe in der Pfanne verdampfen lassen. Die Sahne bei kleiner Hitze einrühren. Wird die Füllung beim Ausbacken zu dick, mit etwas Brühe aus dem Rezept lockern.","notes":"<h3>Tipps</h3><ul><li>Den Teig 30 Minuten ruhen lassen, bevor die Crêpes gebacken werden: Sie werden dünner und lassen sich mit weniger Rissen wenden.</li><li>Das Rindfleisch in dünne Streifen schneiden und portionsweise anbraten: Wird die Pfanne überladen, gibt das Fleisch Wasser ab und dünstet, statt zu bräunen.</li><li>Der erste Crêpe gelingt meist schlechter; er dient dazu, die Hitze und die Fettmenge in der Pfanne anzupassen.</li></ul><h3>Ersetzungen</h3><ul><li>Sahne zum Kochen: Creme fraiche.</li><li>Rinderbrühe: Hühner- oder Gemüsebrühe.</li></ul><h3>Aufbewahrung</h3><p>Crêpes und Füllung getrennt bis zu 3 Tage im Kühlschrank aufbewahren. Die Füllung bei sanfter Hitze aufwärmen und bei Bedarf etwas Brühe hinzufügen, wenn sie zu dick wird.</p><h3>Quelle</h3><p class=\"md-sources\">Quelle: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-minimum-internal-temperature\" rel=\"noopener\" target=\"_blank\">USDA FSIS, sichere Mindest-Kerntemperaturen</a> (auf Englisch).</p><h3>Weitere Fleischgerichte für den Speiseplan</h3><ul><li><a href=\"/de/schweinefleisch-bondiola-rezept/\">Saftiger Schweinenacken aus dem Ofen, mit Alufolie</a></li><li><a href=\"/de/chorizo-santarosano/\">Santarrosano-Chorizo selber machen: frische Wurst</a></li></ul>","steps":[{"title":"Trockene Zutaten mischen","content":"Mehl, Zucker und Salz vermischen."},{"title":"Teig zubereiten","content":"Die Eier verquirlen, Milch und geschmolzene Butter hinzufügen und mit den trockenen Zutaten zu einem klumpenfreien Teig verrühren. Den Teig abdecken und vor dem Ausbacken 30 Minuten ruhen lassen; diese Ruhezeit ist in den insgesamt 90 Minuten enthalten.","image_alt":"Flüssiger Crêpe-Teig in einer Glasschüssel verquirlt","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Crêpes backen","content":"Dünne Crêpes 1 bis 2 Minuten pro Seite in einer leicht gefetteten Pfanne backen und beiseitestellen.","image_alt":"Dünner Crêpe bräunt in einer Pfanne","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Zwiebel und Knoblauch anbraten","content":"Die Butter für die Füllung schmelzen und Zwiebel und Knoblauch anbraten."},{"title":"Rindfleisch anbraten","content":"Das Rindfleisch dazugeben und 3 bis 4 Minuten anbraten; die Champignons hinzufügen und garen, bis sie weich sind.","image_alt":"Rinderstreifen und Champignons bräunen in der Pfanne","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Mehl hinzufügen","content":"Das Mehl darüberstreuen und eine Minute lang verrühren, damit es sich klumpenfrei einbindet."},{"title":"Sauce zubereiten","content":"Die Brühe nach und nach unter Rühren hinzufügen und kochen, bis die Sauce eindickt.","image_alt":"Cremige Champignon-Rindfleisch-Sauce fertig in der Pfanne","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Sahne hinzufügen","content":"Die Sahne unterrühren und einige Minuten bei sanfter Hitze köcheln lassen, ohne stark aufzukochen.","image_alt":"Sahne wird in einem dünnen Strahl über die Rindfleisch-Champignon-Sauce gegossen","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Füllen und servieren","content":"Mit Salz und Pfeffer abschmecken, die Crêpes füllen oder bedecken und mit Petersilie abschließen."}],"total_time_minutes":90,"seo":{"faq":[{"a":"Ja, du kannst sie bis zu einen Tag vorher kochen und gestapelt mit Papier dazwischen, abgedeckt, im Kühlschrank aufbewahren. Die Füllung vor dem Zusammensetzen getrennt aufwärmen.","q":"Kann ich die Crêpes im Voraus zubereiten?"},{"a":"Du kannst Creme fraiche oder ungesüßten Naturjoghurt verwenden, allerdings wird die Sauce dann etwas weniger sämig.","q":"Kann ich die Sahne durch etwas anderes ersetzen?"},{"a":"Ja, die Füllung lässt sich bis zu 2 Monate in einem luftdichten Behälter einfrieren. Die Crêpes sollten besser frisch gebacken werden, da sie beim Einfrieren an Textur verlieren.","q":"Kann ich die Rindfleisch-Champignon-Füllung einfrieren?"},{"q":"Ist das der Stroganoff-Crêpe von Crepes & Waffles?","a":"Es ist eine hausgemachte Variante mit Rindfleisch, Pilzen und cremiger Sauce, kein offizielles oder nachweislich identisches Restaurantrezept."},{"q":"Warum reißen die Crêpes?","a":"Den Teig 30 Minuten ruhen lassen und erneut rühren. Eine heiße, leicht gefettete Antihaftpfanne verwenden und erst wenden, wenn sich die Ränder lösen."}],"title":"Rinder-Stroganoff-Crêpes mit Champignons","description":"Crêpes mit Rindfleisch, Champignons und cremiger Sauce. Für 4 Personen, etwa 90 Minuten einschließlich 30 Minuten Teigruhe.","rest_time_minutes":30}}},{"id":"9708424f-7580-4e3f-930a-3e16cbfec6ba","language":"en","public_path":"/en/creep-stroganoff","recipe_group_id":"6ebd3387-890e-47d2-a9a2-4fabdcc46bb2","expected_updated_at":"2026-10-21T13:48:02.819322+00:00","after":{"excerpt":"Beef and mushroom crepes in a creamy sauce. Serves 4 in about 90 minutes, including 30 minutes of batter resting.","summary":"These homemade Stroganoff crepes combine a thin flour, milk and egg batter with beef, mushrooms and a creamy sauce. The recipe serves 4 and does not claim to reproduce a restaurant chain's recipe.\n\nLet the mushrooms release and evaporate their water before adding the stock. Stir in the cream over low heat. If the filling thickens while you cook the crepes, loosen it with a little of the recipe's stock.","notes":"<h3>Tips</h3><ul><li>Let the batter rest for 30 minutes before cooking the crepes: they turn out thinner and flip with fewer tears.</li><li>Cut the beef into thin strips and brown it in batches: if the pan is crowded, the meat releases water and steams instead of browning.</li><li>The first crepe usually comes out worse; use it to adjust the heat and the amount of fat in the pan.</li></ul><h3>Substitutions</h3><ul><li>Heavy cream: creme fraiche or sour cream.</li><li>Beef broth: chicken or vegetable broth.</li></ul><h3>Storage</h3><p>Store the crepes and the filling separately in the fridge for up to 3 days. Reheat the filling over low heat and add a little broth if it thickens too much.</p><h3>Source</h3><p class=\"md-sources\">Source: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-minimum-internal-temperature\" rel=\"noopener\" target=\"_blank\">USDA FSIS, safe minimum internal temperatures</a>.</p><h3>More meat recipes for another meal</h3><ul><li><a href=\"/en/pork-bondiola-recipe/\">Juicy Oven-Roasted Pork Neck (Bondiola), Foil-Covered</a></li><li><a href=\"/en/chorizo-santarosano/\">Homemade Santarrosano Chorizo: Fresh Colombian Sausage</a></li></ul>","steps":[{"title":"Mix the dry ingredients","content":"Mix the flour, sugar and salt."},{"title":"Make the batter","content":"Beat the eggs, add the milk and melted butter, and combine with the dry ingredients until you have a lump-free batter. Cover the batter and let it rest for 30 minutes before cooking the crepes; this rest is included in the 90-minute total.","image_alt":"Crepe batter whisked in a glass bowl","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cook the crepes","content":"Cook thin crepes, 1 to 2 minutes per side, in a lightly greased pan, and set them aside.","image_alt":"Thin crepe browning in a pan","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Saute the onion and garlic","content":"Melt the butter for the filling and saute the onion and garlic."},{"title":"Brown the beef","content":"Add the beef and brown it for 3 to 4 minutes; add the mushrooms and cook until tender.","image_alt":"Beef strips and mushrooms browning in the pan","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Add the flour","content":"Sprinkle in the flour and stir for a minute so it blends in without lumps."},{"title":"Make the sauce","content":"Add the broth little by little, stirring, and cook until the sauce thickens.","image_alt":"Creamy mushroom and beef sauce ready in the pan","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Add the cream","content":"Stir in the cream and cook a few minutes over low heat, without letting it boil hard.","image_alt":"Cream being poured in a thin stream over the beef and mushroom sauce","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Fill and serve","content":"Season with salt and pepper, fill or top the crepes, and finish with parsley."}],"total_time_minutes":90,"seo":{"faq":[{"a":"Yes, you can cook them up to a day ahead and store them stacked with paper between each one, covered, in the fridge. Reheat the filling separately before assembling.","q":"Can I make the crepes ahead of time?"},{"a":"You can use creme fraiche or plain unsweetened yogurt, although the sauce will be a little less rich.","q":"Can I substitute the cream with something else?"},{"a":"Yes, the filling freezes well for up to 2 months in an airtight container. It's best to cook the crepes fresh, since they lose texture when frozen.","q":"Can I freeze the beef and mushroom filling?"},{"q":"Is this the Crepes & Waffles Stroganoff crepe?","a":"It is a homemade beef and mushroom crepe with a creamy sauce, not an official or verified copy of the restaurant's recipe."},{"q":"Why do my crepes tear?","a":"Rest the batter for 30 minutes, then whisk again. Use a hot, lightly greased nonstick pan and turn each crepe once its edges lift."}],"title":"Beef Stroganoff Crepes with Mushrooms","description":"Beef and mushroom crepes in a creamy sauce. Serves 4 in about 90 minutes, including 30 minutes of batter resting.","rest_time_minutes":30}}},{"id":"8358b894-382b-4032-a693-2b57df99bb3f","language":"es","public_path":"/creep-stroganoff","recipe_group_id":"6ebd3387-890e-47d2-a9a2-4fabdcc46bb2","expected_updated_at":"2026-10-07T01:12:39.564667+00:00","after":{"excerpt":"Crepes de ternera y champiñones con salsa cremosa. Para 4 personas, en unos 90 minutos incluidos 30 de reposo de la masa.","summary":"Los crepes de ternera Stroganoff llevan dos preparaciones: una masa fina de harina, leche y huevo, y un relleno de carne, champiñones y salsa cremosa. Esta versión casera rinde 4 porciones y no pretende reproducir la receta de una cadena de restaurantes.\n\nPara que el relleno no quede aguado, seca los champiñones y deja que pierdan su agua en la sartén antes de incorporar el caldo. Añade la nata a fuego suave. Si la salsa se espesa mientras cocinas los crepes, afloja con un poco del caldo de la receta.","notes":"<h3>Consejos</h3><ul><li>Deja reposar la masa 30 minutos antes de cocinar los crepes: queda más fina y se voltea con menos roturas.</li><li>Corta la ternera en tiras finas y dórala en tandas: si se amontona en la sartén, suelta agua y se cuece en lugar de dorarse.</li><li>El primer crepe suele salir peor; sirve para ajustar el fuego y la cantidad de grasa de la sartén.</li></ul><h3>Sustituciones</h3><ul><li>Nata para cocinar: crema de leche.</li><li>Caldo de res: caldo de pollo o de verduras.</li></ul><h3>Conservación</h3><p>Guarda los crepes y el relleno por separado en la nevera hasta 3 días. Recalienta el relleno a fuego suave y añade un poco de caldo si se espesa.</p><h3>Fuente</h3><p class=\"md-sources\">Fuente: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-minimum-internal-temperature\" rel=\"noopener\" target=\"_blank\">USDA FSIS, temperaturas internas mínimas seguras</a> (en inglés).</p><h3>Otras recetas de carne para variar el menú</h3><ul><li><a href=\"/receta-bondiola-de-cerdo/\">Bondiola de cerdo al horno jugosa, con papel aluminio</a></li><li><a href=\"/chorizo-santarosano/\">Chorizo santarrosano casero: receta fresca paso a paso</a></li></ul>","steps":[{"title":"Mezcla los ingredientes secos","content":"Mezcla la harina, el azúcar y la sal."},{"title":"Prepara la masa","content":"Bate los huevos, añade la leche y la mantequilla derretida, e intégralos con los ingredientes secos hasta obtener una masa sin grumos. Tapa la masa y déjala reposar 30 minutos antes de cocinar los crepes; este reposo está incluido en los 90 minutos totales.","image_alt":"Masa líquida para crepes batida en un bol de cristal","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cocina los crepes","content":"Cocina crepes finos, de 1 a 2 minutos por lado, en una sartén ligeramente engrasada y resérvalos.","image_alt":"Crepe fino dorándose en una sartén","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Sofríe cebolla y ajo","content":"Derrite la mantequilla del relleno y sofríe la cebolla y el ajo."},{"title":"Dora la ternera","content":"Añade la ternera y dórala de 3 a 4 minutos; incorpora los champiñones y cocina hasta que estén tiernos.","image_alt":"Tiras de ternera y champiñones dorándose en la sartén","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Añade la harina","content":"Espolvorea la harina y mezcla durante un minuto para que se integre sin grumos."},{"title":"Prepara la salsa","content":"Añade el caldo poco a poco, removiendo, y cocina hasta que la salsa espese.","image_alt":"Salsa cremosa de champiñones y ternera lista en la sartén","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Agrega la nata","content":"Incorpora la nata y cocina unos minutos a fuego suave, sin que hierva con fuerza.","image_alt":"Nata cayendo en hilo sobre la salsa de ternera y champiñones","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Rellena y sirve","content":"Sazona con sal y pimienta, rellena o cubre los crepes y termina con perejil."}],"total_time_minutes":90,"keywords":["crepe de stroganoff","crepes de ternera","crepes con champiñones","salsa stroganoff","crepes salados"],"seo":{"faq":[{"a":"Sí, se pueden cocinar hasta con un día de antelación y guardarlos apilados con papel entre cada uno, cubiertos en la nevera. Recalienta el relleno por separado antes de montar.","q":"¿Puedo preparar los crepes con antelación?"},{"a":"Puedes usar crema de leche para cocinar o yogur natural sin azúcar, aunque la salsa quedará algo menos untuosa.","q":"¿Puedo sustituir la nata por otro ingrediente?"},{"a":"Sí, el relleno se congela bien hasta 2 meses en un recipiente hermético. Los crepes es mejor cocinarlos frescos, ya que pierden textura al congelarse.","q":"¿Se puede congelar el relleno de ternera y champiñones?"},{"q":"¿Es el crepe Stroganoff de Crepes & Waffles?","a":"Es una versión casera de crepes de ternera con champiñones y salsa cremosa. No es una receta oficial ni una reproducción verificada del restaurante."},{"q":"¿Por qué se rompe la masa del crepe?","a":"Deja reposar la masa 30 minutos y bate de nuevo. Usa una sartén antiadherente caliente, ligeramente engrasada, y gira el crepe cuando los bordes se despeguen."}],"title":"Crepes de ternera Stroganoff con champiñones","description":"Crepes de ternera y champiñones con salsa cremosa. Para 4 personas, en unos 90 minutos incluidos 30 de reposo de la masa.","rest_time_minutes":30}}},{"id":"9dbfe294-f3eb-4c6c-a450-a1a4aee60013","language":"fr","public_path":"/fr/fluage-stroganoff","recipe_group_id":"6ebd3387-890e-47d2-a9a2-4fabdcc46bb2","expected_updated_at":"2026-10-21T13:48:02.819322+00:00","after":{"excerpt":"Crêpes au bœuf et aux champignons, sauce crémeuse. Pour 4 personnes en environ 90 minutes, dont 30 minutes de repos de la pâte.","summary":"Ces crêpes Stroganoff maison associent une pâte fine à base de farine, lait et œufs à une garniture de bœuf, champignons et sauce crémeuse. La recette donne 4 portions et ne prétend pas reproduire celle d'une chaîne de restaurants.\n\nLaissez l'eau des champignons s'évaporer avant d'ajouter le bouillon. Incorporez la crème à feu doux. Si la garniture épaissit pendant la cuisson des crêpes, détendez-la avec un peu du bouillon prévu.","notes":"<h3>Conseils</h3><ul><li>Laisse reposer la pâte 30 minutes avant de cuire les crêpes : elles seront plus fines et se retourneront avec moins de déchirures.</li><li>Coupe le bœuf en fines lanières et fais-le dorer par portions : si la poêle est surchargée, la viande rend de l'eau et cuit à la vapeur au lieu de dorer.</li><li>La première crêpe est souvent moins réussie ; elle sert à ajuster le feu et la quantité de matière grasse dans la poêle.</li></ul><h3>Substitutions</h3><ul><li>Crème fraîche épaisse : crème liquide entière.</li><li>Bouillon de bœuf : bouillon de poulet ou de légumes.</li></ul><h3>Conservation</h3><p>Conserve les crêpes et la garniture séparément au réfrigérateur jusqu'à 3 jours. Réchauffe la garniture à feu doux et ajoute un peu de bouillon si elle a trop épaissi.</p><h3>Source</h3><p class=\"md-sources\">Source : <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-minimum-internal-temperature\" rel=\"noopener\" target=\"_blank\">USDA FSIS, températures internes minimales sûres</a> (en anglais).</p><h3>D'autres recettes de viande pour varier</h3><ul><li><a href=\"/fr/recette-de-porc-bondiola/\">Échine de porc au four, juteuse et cuite sous aluminium</a></li><li><a href=\"/fr/chorizo-santarosano/\">Chorizo santarrosano maison : saucisse colombienne fraîche</a></li></ul>","steps":[{"title":"Mélange les ingrédients secs","content":"Mélange la farine, le sucre et le sel."},{"title":"Prépare la pâte","content":"Bats les œufs, ajoute le lait et le beurre fondu, puis incorpore aux ingrédients secs jusqu'à obtenir une pâte sans grumeaux. Couvrez la pâte et laissez-la reposer 30 minutes avant de cuire les crêpes ; ce repos est inclus dans les 90 minutes au total.","image_alt":"Pâte à crêpes liquide fouettée dans un bol en verre","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cuis les crêpes","content":"Cuis des crêpes fines, 1 à 2 minutes de chaque côté, dans une poêle légèrement graissée, et réserve-les.","image_alt":"Crêpe fine qui dore dans une poêle","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Fais revenir l'oignon et l'ail","content":"Fais fondre le beurre de la garniture et fais revenir l'oignon et l'ail."},{"title":"Fais dorer le bœuf","content":"Ajoute le bœuf et fais-le dorer 3 à 4 minutes ; ajoute les champignons et cuis jusqu'à ce qu'ils soient tendres.","image_alt":"Lanières de bœuf et champignons qui dorent dans la poêle","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Ajoute la farine","content":"Saupoudre la farine et mélange pendant une minute pour qu'elle s'incorpore sans grumeaux."},{"title":"Prépare la sauce","content":"Ajoute le bouillon petit à petit en remuant, et cuis jusqu'à ce que la sauce épaississe.","image_alt":"Sauce crémeuse aux champignons et au bœuf prête dans la poêle","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Ajoute la crème","content":"Incorpore la crème et laisse cuire quelques minutes à feu doux, sans laisser bouillir fort.","image_alt":"Crème versée en filet sur la sauce au bœuf et aux champignons","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Garnis et sers","content":"Assaisonne de sel et de poivre, garnis ou recouvre les crêpes et termine avec du persil."}],"total_time_minutes":90,"seo":{"faq":[{"a":"Oui, tu peux les cuire jusqu'à un jour à l'avance et les conserver empilees avec du papier entre chacune, couvertes, au réfrigérateur. Réchauffe la garniture séparément avant de les assembler.","q":"Puis-je préparer les crêpes à l'avance ?"},{"a":"Tu peux utiliser de la crème liquide ou du yaourt nature non sucre, mais la sauce sera un peu moins onctueuse.","q":"Puis-je remplacer la crème par un autre ingrédient ?"},{"a":"Oui, la garniture se congelé bien jusqu'à 2 mois dans un récipient hermétique. Il vaut mieux cuire les crêpes fraîches, car elles perdent en texture à la congélation.","q":"Peut-on congeler la garniture au bœuf et aux champignons ?"},{"q":"Est-ce la crêpe Stroganoff de Crepes & Waffles ?","a":"C'est une version maison au bœuf, champignons et sauce crémeuse, pas une recette officielle ni une copie vérifiée du restaurant."},{"q":"Pourquoi les crêpes se déchirent-elles ?","a":"Laissez reposer la pâte 30 minutes puis fouettez-la. Utilisez une poêle antiadhésive chaude, légèrement graissée, et retournez quand les bords se décollent."}],"title":"Crêpes au bœuf Stroganoff et aux champignons","description":"Crêpes au bœuf et aux champignons, sauce crémeuse. Pour 4 personnes en environ 90 minutes, dont 30 minutes de repos de la pâte.","rest_time_minutes":30}}},{"id":"b87caa7d-eb4f-49b8-823a-aa89835e7e99","language":"it","public_path":"/it/creep-stroganoff","recipe_group_id":"6ebd3387-890e-47d2-a9a2-4fabdcc46bb2","expected_updated_at":"2026-10-21T13:48:02.819322+00:00","after":{"excerpt":"Crêpes al manzo e funghi con salsa cremosa. Per 4 persone in circa 90 minuti, inclusi 30 minuti di riposo della pastella.","summary":"Queste crêpes Stroganoff casalinghe uniscono una pastella sottile di farina, latte e uova a un ripieno di manzo, funghi e salsa cremosa. La ricetta è per 4 persone e non riproduce quella di una catena di ristoranti.\n\nFate evaporare l'acqua dei funghi prima di aggiungere il brodo. Unite la panna a fuoco basso. Se il ripieno si addensa mentre cuocete le crêpes, allungatelo con poco brodo della ricetta.","notes":"<h3>Consigli</h3><ul><li>Lascia riposare la pastella 30 minuti prima di cuocere le crêpes: risulteranno più sottili e si gireranno con meno rotture.</li><li>Taglia il manzo a listarelle sottili e rosolalo a più riprese: se la padella è troppo piena, la carne rilascia acqua e cuoce al vapore invece di rosolare.</li><li>La prima crêpe di solito viene peggio; serve per regolare il calore e la quantità di grasso nella padella.</li></ul><h3>Sostituzioni</h3><ul><li>Panna da cucina: panna fresca liquida.</li><li>Brodo di manzo: brodo di pollo o vegetale.</li></ul><h3>Conservazione</h3><p>Conserva le crêpes e il ripieno separatamente in frigorifero fino a 3 giorni. Riscalda il ripieno a fuoco dolce e aggiungi un po' di brodo se si addensa troppo.</p><h3>Fonte</h3><p class=\"md-sources\">Fonte: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-minimum-internal-temperature\" rel=\"noopener\" target=\"_blank\">USDA FSIS, temperature interne minime di sicurezza</a> (in inglese).</p><h3>Altre ricette di carne per variare</h3><ul><li><a href=\"/it/ricetta-maiale-bondiola/\">Collo di maiale al forno succoso, coperto con alluminio</a></li><li><a href=\"/it/chorizo-santarosano/\">Chorizo santarrosano fatto in casa: salsiccia fresca</a></li></ul>","steps":[{"title":"Mescola gli ingredienti secchi","content":"Mescola la farina, lo zucchero e il sale."},{"title":"Prepara la pastella","content":"Sbatti le uova, aggiungi il latte e il burro fuso e unisci agli ingredienti secchi fino a ottenere una pastella senza grumi. Coprite la pastella e lasciatela riposare 30 minuti prima di cuocere le crêpes; il riposo è incluso nei 90 minuti totali.","image_alt":"Pastella liquida per crêpes sbattuta in una ciotola di vetro","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cuoci le crêpes","content":"Cuoci crêpes sottili, da 1 a 2 minuti per lato, in una padella leggermente unta, e mettile da parte.","image_alt":"Crêpe sottile che dora in padella","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Soffriggi cipolla e aglio","content":"Sciogli il burro del ripieno e soffriggi la cipolla e l'aglio."},{"title":"Rosola il manzo","content":"Aggiungi il manzo e rosolalo per 3-4 minuti; aggiungi i funghi e cuoci finché sono teneri.","image_alt":"Listarelle di manzo e funghi che rosolano in padella","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Aggiungi la farina","content":"Cospargi la farina e mescola per un minuto affinché si amalgami senza grumi."},{"title":"Prepara la salsa","content":"Aggiungi il brodo poco alla volta, mescolando, e cuoci finché la salsa si addensa.","image_alt":"Salsa cremosa di funghi e manzo pronta in padella","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Aggiungi la panna","content":"Incorpora la panna e cuoci qualche minuto a fuoco dolce, senza farla bollire con forza.","image_alt":"Panna versata a filo sulla salsa di manzo e funghi","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Farcisci e servi","content":"Aggiusta di sale e pepe, farcisci o copri le crêpes e termina con il prezzemolo."}],"total_time_minutes":90,"seo":{"faq":[{"a":"Si, puoi cuocerle fino a un giorno prima e conservarle impilate con carta forno tra una e l'altra, coperte, in frigorifero. Riscalda il ripieno separatamente prima di assemblarle.","q":"Posso preparare le crêpes in anticipo?"},{"a":"Puoi usare panna da cucina liquida o yogurt bianco non zuccherato, anche se la salsa risulterà un po' meno cremosa.","q":"Posso sostituire la panna con un altro ingrediente?"},{"a":"Si, il ripieno si congela bene fino a 2 mesi in un contenitore ermetico. Le crêpes è meglio cuocerle fresche, perché perdono consistenza una volta congelate.","q":"Si può congelare il ripieno di manzo e funghi?"},{"q":"È la crêpe Stroganoff di Crepes & Waffles?","a":"È una versione casalinga con manzo, funghi e salsa cremosa, non una ricetta ufficiale né una copia verificata del ristorante."},{"q":"Perché le crêpes si rompono?","a":"Lasciate riposare la pastella 30 minuti e mescolate di nuovo. Usate una padella antiaderente calda e leggermente unta, girando quando i bordi si staccano."}],"title":"Crêpes al manzo Stroganoff con funghi","description":"Crêpes al manzo e funghi con salsa cremosa. Per 4 persone in circa 90 minuti, inclusi 30 minuti di riposo della pastella.","rest_time_minutes":30}}},{"id":"00631fec-7127-4bec-9379-872c56a2acfc","language":"ja","public_path":"/ja/ビーフストロガノフクレープ","recipe_group_id":"6ebd3387-890e-47d2-a9a2-4fabdcc46bb2","expected_updated_at":"2026-10-07T01:12:39.564667+00:00","after":{"excerpt":"牛肉ときのこをクリーミーなソースで包むクレープ。4人分、所要時間は約90分。生地を30分休ませる時間を含みます。","summary":"小麦粉、牛乳、卵の薄い生地に、牛肉ときのこのクリーミーなソースを包む家庭向けのレシピです。4人分で、特定のレストランチェーンのレシピを再現したものではありません。\n\nきのこの水分をフライパンで飛ばしてからスープを加え、生クリームは弱火で混ぜます。クレープを焼いている間にソースが煮詰まったら、レシピのスープを少量加えて調整します。","notes":"<h3>コツ</h3><ul><li>クレープを焼く前に生地を30分休ませると、より薄く仕上がり、破れにくく裏返せる。</li><li>牛肉は薄切りにして数回に分けて焼く。フライパンに詰め込みすぎると水分が出て、焼き色がつかず蒸し状態になる。</li><li>最初の1枚はうまくいかないことが多いので、フライパンの火加減と油の量を調整するために使うとよい。</li></ul><h3>代用</h3><ul><li>生クリーム（調理用）：生クリーム全般で代用可能。</li><li>ビーフブロス：チキンブロスまたは野菜ブロス。</li></ul><h3>保存</h3><p>クレープと具材は別々に保存容器に入れ、冷蔵庫で3日以内に食べきる。具材は弱火で温め直し、とろみが強すぎる場合は少量のブロスを加える。</p><h3>出典</h3><p class=\"md-sources\">出典：<a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-minimum-internal-temperature\" rel=\"noopener\" target=\"_blank\">USDA FSIS、安全な最低中心温度</a>（英語）。</p><h3>別の日に作りたい肉料理</h3><ul><li><a href=\"/ja/ポークボンディオーラのレシピ/\">ボンディオラのオーブン焼き｜アルミホイルでしっとり</a></li><li><a href=\"/ja/コロンビア風サンタロサノ生チョリソ\">サンタロサノ風チョリソの作り方｜自家製生ソーセージ</a></li></ul>","steps":[{"title":"粉類を混ぜる","content":"小麦粉、砂糖、塩を混ぜ合わせる。"},{"title":"生地を作る","content":"卵を溶き、牛乳と溶かしバターを加えて、粉類とダマがなくなるまで混ぜ合わせる。 生地にふたをして、焼く前に30分休ませます。この休ませ時間は所要時間90分に含まれます。","image_alt":"ガラスボウルで泡立てたクレープ生地","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"クレープを焼く","content":"薄く油を引いたフライパンで、片面1〜2分ずつ薄いクレープを焼き、取り分けておく。","image_alt":"フライパンで焼き色がつく薄いクレープ","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"玉ねぎとにんにくを炒める","content":"具材用のバターを溶かし、玉ねぎとにんにくを炒める。"},{"title":"牛肉を焼く","content":"牛肉を加えて3〜4分焼き色をつけ、マッシュルームを加えて柔らかくなるまで火を通す。","image_alt":"フライパンで焼き色がつく牛肉の細切りとマッシュルーム","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"小麦粉を加える","content":"小麦粉を振り入れ、ダマにならないよう1分ほど混ぜる。"},{"title":"ソースを作る","content":"ブロスを少しずつ加えながら混ぜ、ソースがとろみがつくまで煮る。","image_alt":"フライパンで仕上がったクリーミーなきのこと牛肉のソース","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"生クリームを加える","content":"生クリームを加え、強く沸騰させないよう弱火で数分煮る。","image_alt":"牛肉ときのこのソースに細く生クリームを注ぐ様子","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"包んで盛り付ける","content":"塩こしょうで味を調え、クレープに包むかのせて、パセリを散らして仕上げる。"}],"total_time_minutes":90,"seo":{"faq":[{"a":"はい、1日前まで焼いておくことができます。間に紙を挟んで重ね、冷蔵庫でカバーして保存してください。具材は組み立てる前に別々に温め直してください。","q":"クレープは前もって作れますか？"},{"a":"生クリーム全般や無糖プレーンヨーグルトで代用できますが、ソースの濃厚さは少し劣ります。","q":"生クリームを他のもので代用できますか？"},{"a":"はい、密閉容器に入れれば最大2か月冷凍できます。クレープは冷凍すると食感が落ちるため、その都度焼くことをおすすめします。","q":"牛肉ときのこの具材は冷凍できますか？"},{"q":"Crepes & Wafflesのストロガノフクレープですか？","a":"牛肉、きのこ、クリーミーなソースを使う家庭向けのアレンジです。お店の公式レシピや、検証済みの再現レシピではありません。"},{"q":"クレープが破れるのはなぜですか？","a":"生地を30分休ませて混ぜ直します。薄く油を塗った、十分に温めた焦げ付きにくいフライパンを使い、縁がはがれてから裏返してください。"}],"title":"ビーフストロガノフ風クレープ きのこ添え","description":"牛肉ときのこをクリーミーなソースで包むクレープ。4人分、所要時間は約90分。生地を30分休ませる時間を含みます。","rest_time_minutes":30}}},{"id":"fd9286e6-bae7-4889-9558-7e34ff073824","language":"pt","public_path":"/pt/panquecas-carne-stroganoff-cogumelos","recipe_group_id":"6ebd3387-890e-47d2-a9a2-4fabdcc46bb2","expected_updated_at":"2026-10-12T07:55:43.642808+00:00","after":{"excerpt":"Panquecas de carne e cogumelos com molho cremoso. Para 4 pessoas, em cerca de 90 minutos, incluindo 30 minutos de descanso da massa.","summary":"Estas panquecas Stroganoff caseiras juntam massa fina de farinha, leite e ovos com recheio de carne, cogumelos e molho cremoso. Rendem 4 porções e não pretendem reproduzir a receita de uma rede de restaurantes.\n\nDeixe a água dos cogumelos evaporar antes de adicionar o caldo. Incorpore o creme de leite em fogo baixo. Se o recheio engrossar enquanto faz as panquecas, ajuste com um pouco do caldo da receita.","notes":"<h3>Dicas</h3><ul><li>Deixe a massa descansar 30 minutos antes de cozinhar as panquecas: ficam mais finas e viram-se com menos rasgos.</li><li>Corte a carne em tiras finas e doure-a em lotes: se a frigideira ficar cheia, a carne solta água e cozinha em vez de dourar.</li><li>A primeira panqueca costuma sair pior; serve para ajustar o calor e a quantidade de gordura na frigideira.</li></ul><h3>Substituições</h3><ul><li>Natas para cozinhar: creme de leite fresco.</li><li>Caldo de carne: caldo de galinha ou de legumes.</li></ul><h3>Conservação</h3><p>Guarde as panquecas e o recheio separadamente no frigorífico até 3 dias. Reaqueça o recheio em fogo brando e junte um pouco de caldo se engrossar demasiado.</p><h3>Fonte</h3><p class=\"md-sources\">Fonte: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-minimum-internal-temperature\" rel=\"noopener\" target=\"_blank\">USDA FSIS, temperaturas internas mínimas seguras</a> (em inglês).</p><h3>Outras receitas de carne para variar</h3><ul><li><a href=\"/pt/bondiola-de-porco-assada-no-forno\">Bondiola de porco no forno, suculenta no papel-alumínio</a></li><li><a href=\"/pt/chourico-santarrosano-fresco\">Chouriço santarrosano caseiro: receita fresca</a></li></ul>","steps":[{"title":"Misture os ingredientes secos","content":"Misture a farinha, o açúcar e o sal."},{"title":"Prepare a massa","content":"Bata os ovos, junte o leite e a manteiga derretida, e misture com os ingredientes secos até obter uma massa sem grumos. Cubra a massa e deixe descansar por 30 minutos antes de fazer as panquecas; esse descanso está incluído nos 90 minutos totais.","image_alt":"Massa líquida de panqueca batida numa tigela de vidro","image_url":"/recetas/creep-stroganoff/paso-02.webp"},{"title":"Cozinhe as panquecas","content":"Cozinhe panquecas finas, de 1 a 2 minutos de cada lado, numa frigideira levemente untada, e reserve-as.","image_alt":"Panqueca fina a dourar numa frigideira","image_url":"/recetas/creep-stroganoff/paso-03.webp"},{"title":"Refogue a cebola e o alho","content":"Derreta a manteiga do recheio e refogue a cebola e o alho."},{"title":"Doure a carne","content":"Junte a carne e doure-a por 3 a 4 minutos; acrescente os cogumelos e cozinhe até ficarem macios.","image_alt":"Tiras de carne e cogumelos a dourar na frigideira","image_url":"/recetas/creep-stroganoff/paso-05.webp"},{"title":"Adicione a farinha","content":"Polvilhe a farinha e mexa durante um minuto para incorporar sem grumos."},{"title":"Prepare o molho","content":"Adicione o caldo aos poucos, mexendo, e cozinhe até o molho engrossar.","image_alt":"Molho cremoso de cogumelos e carne pronto na frigideira","image_url":"/recetas/creep-stroganoff/paso-07.webp"},{"title":"Adicione as natas","content":"Junte as natas e cozinhe alguns minutos em fogo brando, sem deixar ferver com força.","image_alt":"Natas a cair em fio sobre o molho de carne e cogumelos","image_url":"/recetas/creep-stroganoff/paso-08.webp"},{"title":"Recheie e sirva","content":"Tempere com sal e pimenta, recheie ou cubra as panquecas e finalize com salsa."}],"total_time_minutes":90,"seo":{"faq":[{"a":"Sim, pode cozinha-las até um dia antes e guarda-las empilhadas com papel entre cada uma, cobertas, no frigorífico. Reaqueça o recheio separadamente antes de montar.","q":"Posso preparar as panquecas com antecedência?"},{"a":"Pode usar creme de leite fresco ou iogurte natural sem açúcar, embora o molho fique um pouco menos cremoso.","q":"Posso substituir as natas por outro ingrediente?"},{"a":"Sim, o recheio congela bem até 2 meses num recipiente hermético. As panquecas e melhor cozinha-las frescas, pois perdem textura ao congelar.","q":"Posso congelar o recheio de carne e cogumelos?"},{"q":"É o crepe Stroganoff do Crepes & Waffles?","a":"É uma versão caseira com carne, cogumelos e molho cremoso, não uma receita oficial nem uma cópia verificada do restaurante."},{"q":"Por que a panqueca rasga?","a":"Deixe a massa descansar 30 minutos e bata novamente. Use frigideira antiaderente quente, levemente untada, e vire quando as bordas se soltarem."}],"title":"Panquecas de carne Stroganoff com cogumelos","description":"Panquecas de carne e cogumelos com molho cremoso. Para 4 pessoas, em cerca de 90 minutos, incluindo 30 minutos de descanso da massa.","rest_time_minutes":30}}},{"id":"702bee80-233d-4477-b545-f5e66bb647ad","language":"de","public_path":"/de/schweinefleisch-bondiola-rezept","recipe_group_id":"af4f77b1-24cd-4c6f-8d02-dbc92e3cfc24","expected_updated_at":"2026-10-25T04:48:08.371477+00:00","after":{"title":"Saftiger Schweinenacken aus dem Ofen, mit Alufolie","notes":"<p>Bei 2 kg nach etwa 2 Stunden zugedecktem Garen bei 160 °C die Zartheit prüfen. Dicke und Ofen beeinflussen die Zeit: Ist das Fleisch noch fest, zugedeckt weitergaren und auf Flüssigkeit im Bräter achten. 1 kg benötigt nicht zwingend die halbe Zeit.</p><p>Alufolie über dem Bräter hält Feuchtigkeit zurück; das Fleisch nicht eng einwickeln. Erst zum Bräunen abdecken und den Honig beobachten. Für ein ganzes Stück Schweinefleisch gelten mindestens 63 °C mit 3 Minuten Ruhezeit; hier werden für die Zartheit 80–85 °C angestrebt und mit einer Gabel geprüft.</p><p>15 Minuten ruhen lassen, quer zur Faser schneiden. Reste mit Bratensaft auf 74 °C im Kern erhitzen.</p><h3>Aufbewahrung</h3><p>Fleisch und Bratensaft innerhalb von 2 Stunden nach dem Herausnehmen aus dem Ofen in geschlossenen Behältern kühlen. Hält sich 3 bis 4 Tage und wird sanft mit etwas Sauce bis 74 °C erhitzt. Portionsweise bis zu 3 Monate einfrierbar.</p><p class='md-sources'>Quellen: <a href='https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart' rel='noopener' target='_blank'>USDA FSIS, sichere Mindesttemperaturen</a>; <a href='https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety' rel='noopener' target='_blank'>USDA FSIS, Reste und Lebensmittelsicherheit</a> (beide auf Englisch).</p><p>Quellen: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>Weitere Fleischgerichte für den Speiseplan</h3><ul><li><a href=\"/de/creep-stroganoff/\">Rinder-Stroganoff-Crêpes mit Champignons</a></li><li><a href=\"/de/chorizo-santarosano/\">Santarrosano-Chorizo selber machen: frische Wurst</a></li></ul>","seo":{"faq":[{"q":"Welches Teilstück ist Bondiola?","a":"Marmorierter Schweinenacken, der sich zum langsamen Garen eignet. Die Bezeichnung unterscheidet sich je nach Land."},{"q":"Wie lange brauchen 2 kg Schweinenacken?","a":"Nach etwa 2 Stunden zugedeckt bei 160 °C prüfen. Bei Bedarf mit Flüssigkeit im Bräter zugedeckt weitergaren; die Dicke zählt mit. Zum Schluss 15–20 Minuten offen bei 200 °C bräunen."},{"q":"Wie verwende ich Alufolie?","a":"Den Bräter beim langsamen Garen mit Folie abdecken, zum Bräunen öffnen. Bei Bedarf heißes Wasser nachgießen."},{"q":"Warum ist der gegarte Nacken noch zäh?","a":"Eine sichere Mindesttemperatur garantiert keine Zartheit. Schonend zugedeckt weitergaren; hier werden 80–85 °C und eine mit der Gabel leicht teilbare Textur angestrebt."}],"title":"Saftiger Schweinenacken aus dem Ofen, mit Alufolie","description":"2 kg Schweinenacken mit Senf, Honig und Knoblauch. Zugedeckt unter Alufolie garen, Kerntemperatur prüfen, ruhen lassen und Bratensauce zubereiten."}}},{"id":"b705a6a3-ad43-4226-b8c5-6ff08f9b849e","language":"en","public_path":"/en/pork-bondiola-recipe","recipe_group_id":"af4f77b1-24cd-4c6f-8d02-dbc92e3cfc24","expected_updated_at":"2026-10-25T04:48:08.371477+00:00","after":{"title":"Juicy Oven-Roasted Pork Neck (Bondiola), Foil-Covered","notes":"<p>For a 2 kg piece, start checking tenderness after about 2 hours covered at 160 °C (320 °F). Thickness and ovens change the timing: if still firm, continue covered and keep liquid in the pan. A 1 kg piece will not necessarily take half the time.</p><p>Cover the roasting pan with foil to retain moisture; there is no need to wrap the meat tightly. Uncover only to brown and watch the honey. Whole pork has a safe minimum of 63 °C (145 °F) with 3 minutes of rest; this recipe aims for 80–85 °C for tenderness, also checking with a fork.</p><p>Rest for 15 minutes and slice against the grain. Reheat leftovers with their juices to 74 °C (165 °F) in the center.</p><h3>Storage</h3><p>Refrigerate the meat and juices within 2 hours of taking it out of the oven, in closed containers. It keeps for 3 to 4 days and reheats gently with some of the sauce to 165°F (74°C). You can freeze it in portions for up to 3 months.</p><p class='md-sources'>Sources: <a href='https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart' rel='noopener' target='_blank'>USDA FSIS, minimum safe temperatures</a>; <a href='https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety' rel='noopener' target='_blank'>USDA FSIS, leftovers and food safety</a>.</p><p>References: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>More meat recipes for another meal</h3><ul><li><a href=\"/en/creep-stroganoff/\">Beef Stroganoff Crepes with Mushrooms</a></li><li><a href=\"/en/chorizo-santarosano/\">Homemade Santarrosano Chorizo: Fresh Colombian Sausage</a></li></ul>","seo":{"faq":[{"q":"What cut is bondiola?","a":"It is a marbled pork neck cut suited to slow cooking. Ask your butcher for pork neck; names differ between countries."},{"q":"How long does a 2 kg pork neck take?","a":"Start checking after about 2 hours covered at 160 °C (320 °F). If not tender, continue covered with liquid in the pan; thickness also matters. Finally uncover and brown for 15–20 minutes at 200 °C (400 °F)."},{"q":"How do I use foil?","a":"Cover the roasting pan to retain steam during slow cooking, then uncover to brown. Add hot water to the pan if it runs dry."},{"q":"Why is cooked pork neck still tough?","a":"A safe minimum temperature does not ensure the connective tissue is tender. Continue gentle covered cooking; this recipe aims for 80–85 °C and a fork-tender texture."}],"title":"Juicy Oven-Roasted Pork Neck (Bondiola), Foil-Covered","description":"Roast a 2 kg pork neck with mustard, honey and garlic. Covered baking with foil, internal temperature, resting and pan sauce explained step by step."}}},{"id":"067c8e64-4822-4ea8-945d-be7193b40a95","language":"es","public_path":"/receta-bondiola-de-cerdo","recipe_group_id":"af4f77b1-24cd-4c6f-8d02-dbc92e3cfc24","expected_updated_at":"2026-10-07T01:12:39.564667+00:00","after":{"title":"Bondiola de cerdo al horno jugosa, con papel aluminio","notes":"<p>Para una pieza de 2 kg, empieza a comprobar la terneza tras unas 2 horas tapada a 160 °C. El grosor y el horno cambian el tiempo: si sigue firme, continúa tapada y revisa que haya líquido en la asadera. Una pieza de 1 kg no tarda necesariamente la mitad.</p><p>El aluminio cubre la asadera para retener humedad; no hace falta envolver la carne apretadamente. Retíralo solo para dorar y vigila la miel. El mínimo seguro para una pieza entera de cerdo es 63 °C y 3 minutos de reposo; esta receta busca 80–85 °C para ablandar el corte, además de comprobar su terneza con un tenedor.</p><p>Deja reposar 15 minutos y corta contra la fibra. Para recalentar las sobras, añade sus jugos y calienta hasta 74 °C en el centro.</p><h3>Conservación</h3><p>Refrigera la carne y los jugos dentro de las 2 horas siguientes a sacarla del horno, en recipientes cerrados. Se conserva de 3 a 4 días y se recalienta suavemente con parte de la salsa hasta 74 °C. Puedes congelarla en porciones hasta 3 meses.</p><p class=\"md-sources\">Fuentes: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart\" rel=\"noopener\" target=\"_blank\">USDA FSIS, temperaturas mínimas seguras</a>; <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety\" rel=\"noopener\" target=\"_blank\">USDA FSIS, sobras y seguridad alimentaria</a> (ambas en inglés).</p><p>Referencias: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>Otras recetas de carne para variar el menú</h3><ul><li><a href=\"/creep-stroganoff/\">Crepes de ternera Stroganoff con champiñones</a></li><li><a href=\"/chorizo-santarosano/\">Chorizo santarrosano casero: receta fresca paso a paso</a></li></ul>","keywords":["bondiola de cerdo al horno","bondiola con papel aluminio","bondiola de 2 kg","bondiola jugosa","cuello de cerdo al horno"],"seo":{"faq":[{"q":"¿Qué corte es la bondiola de cerdo?","a":"Es un corte del cuello del cerdo, con grasa entreverada, adecuado para cocción lenta. Según el país, pregunta por cuello o cabeza de lomo."},{"q":"¿Cuánto tiempo necesita una bondiola de 2 kg?","a":"Empieza a revisar tras unas 2 horas tapada a 160 °C. Si no está tierna, continúa tapada con líquido en el fondo; el tiempo depende también del grosor. Al final, destapa y dora 15–20 minutos a 200 °C."},{"q":"¿Cómo se hace con papel aluminio?","a":"Cubre la asadera con aluminio para retener vapor durante la cocción lenta. Destapa al final para dorar. Si falta líquido, añade agua caliente al fondo."},{"q":"¿Por qué queda dura aunque esté cocida?","a":"El mínimo seguro no garantiza que se haya ablandado el tejido conectivo. Continúa la cocción suave y tapada; esta receta busca 80–85 °C y una textura tierna al pinchar con un tenedor."}],"title":"Bondiola de cerdo al horno jugosa, con papel aluminio","description":"Bondiola de cerdo al horno con mostaza, miel y ajo. Pieza de 2 kg, cocción tapada con papel aluminio, temperatura interna y reposo paso a paso."}}},{"id":"09c2ab9b-2c60-4099-9eb2-1c4d06b74a0b","language":"fr","public_path":"/fr/recette-de-porc-bondiola","recipe_group_id":"af4f77b1-24cd-4c6f-8d02-dbc92e3cfc24","expected_updated_at":"2026-10-25T04:48:08.371477+00:00","after":{"title":"Échine de porc au four, juteuse et cuite sous aluminium","notes":"<p>Pour 2 kg, vérifiez la tendreté après environ 2 heures à couvert à 160 °C. L'épaisseur et le four modifient le temps : si la viande reste ferme, poursuivez à couvert avec du liquide dans le plat. Un morceau de 1 kg ne demande pas forcément deux fois moins de temps.</p><p>Couvrez le plat d'aluminium pour garder l'humidité, sans emballer la viande serrée. Découvrez pour dorer en surveillant le miel. Le minimum sûr pour une pièce entière de porc est de 63 °C avec 3 minutes de repos ; ici, on vise 80–85 °C pour attendrir ce morceau, avec contrôle à la fourchette.</p><p>Laissez reposer 15 minutes et tranchez contre les fibres. Réchauffez les restes avec leur jus jusqu'à 74 °C au centre.</p><h3>Conservation</h3><p>Réfrigère la viande et les jus dans les 2 heures suivant la sortie du four, dans des récipients fermés. Se conserve 3 à 4 jours et se réchauffe doucement avec un peu de sauce jusqu'à 74 °C. Peut se congeler en portions jusqu'à 3 mois.</p><p class='md-sources'>Sources : <a href='https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart' rel='noopener' target='_blank'>USDA FSIS, températures minimales sûres</a> ; <a href='https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety' rel='noopener' target='_blank'>USDA FSIS, restes et sécurité alimentaire</a> (en anglais).</p><p>Sources: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>D'autres recettes de viande pour varier</h3><ul><li><a href=\"/fr/fluage-stroganoff/\">Crêpes au bœuf Stroganoff et aux champignons</a></li><li><a href=\"/fr/chorizo-santarosano/\">Chorizo santarrosano maison : saucisse colombienne fraîche</a></li></ul>","seo":{"faq":[{"q":"Quel morceau est la bondiola ?","a":"C'est de l'échine de porc persillée, adaptée à la cuisson lente. Le nom varie selon les pays."},{"q":"Combien de temps pour une échine de 2 kg ?","a":"Vérifiez après environ 2 heures à couvert à 160 °C. Poursuivez si nécessaire, avec du liquide ; l'épaisseur compte aussi. Dorez ensuite à découvert 15–20 minutes à 200 °C."},{"q":"Comment utiliser l'aluminium ?","a":"Couvrez le plat pour conserver la vapeur pendant la cuisson lente, puis découvrez pour dorer. Ajoutez de l'eau chaude au fond si nécessaire."},{"q":"Pourquoi l'échine cuite reste-t-elle ferme ?","a":"La température minimale sûre ne garantit pas une viande tendre. Poursuivez doucement à couvert ; cette recette vise 80–85 °C et une texture tendre à la fourchette."}],"title":"Échine de porc au four, juteuse et cuite sous aluminium","description":"Échine de porc de 2 kg à la moutarde, au miel et à l'ail. Cuisson sous aluminium, température à cœur, repos et sauce au jus expliqués pas à pas."}}},{"id":"73b7a347-1fc2-4a23-a6f6-974400575731","language":"it","public_path":"/it/ricetta-maiale-bondiola","recipe_group_id":"af4f77b1-24cd-4c6f-8d02-dbc92e3cfc24","expected_updated_at":"2026-10-25T04:48:08.371477+00:00","after":{"title":"Collo di maiale al forno succoso, coperto con alluminio","notes":"<p>Per 2 kg, iniziate a controllare la tenerezza dopo circa 2 ore coperto a 160 °C. Spessore e forno cambiano i tempi: se è ancora duro, proseguite coperto mantenendo liquido nella teglia. Un pezzo da 1 kg non richiede necessariamente metà tempo.</p><p>Coprite la teglia con alluminio per trattenere l'umidità, senza avvolgere strettamente la carne. Scoprite per dorare, sorvegliando il miele. Il minimo sicuro per un pezzo intero di maiale è 63 °C con 3 minuti di riposo; qui si cercano 80–85 °C per la tenerezza, controllando anche con una forchetta.</p><p>Fate riposare 15 minuti e affettate contro fibra. Riscaldate gli avanzi con il sugo fino a 74 °C al centro.</p><h3>Conservazione</h3><p>Metti in frigorifero carne e fondo di cottura entro 2 ore dall'uscita dal forno, in contenitori chiusi. Si conserva 3-4 giorni e si riscalda delicatamente con un po' di salsa fino a 74 °C. Si può congelare in porzioni fino a 3 mesi.</p><p class='md-sources'>Fonti: <a href='https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart' rel='noopener' target='_blank'>USDA FSIS, temperature minime sicure</a>; <a href='https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety' rel='noopener' target='_blank'>USDA FSIS, avanzi e sicurezza alimentare</a> (in inglese).</p><p>Fonti: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>Altre ricette di carne per variare</h3><ul><li><a href=\"/it/creep-stroganoff/\">Crêpes al manzo Stroganoff con funghi</a></li><li><a href=\"/it/chorizo-santarosano/\">Chorizo santarrosano fatto in casa: salsiccia fresca</a></li></ul>","seo":{"faq":[{"q":"Che taglio è la bondiola?","a":"È collo di maiale marezzato, adatto alla cottura lenta. Il nome può cambiare secondo il paese."},{"q":"Quanto cuoce un pezzo da 2 kg?","a":"Controllate dopo circa 2 ore coperto a 160 °C. Proseguite se serve mantenendo liquido nella teglia; conta anche lo spessore. Dorate infine scoperto 15–20 minuti a 200 °C."},{"q":"Come si usa l'alluminio?","a":"Coprite la teglia per trattenere il vapore durante la cottura lenta, poi scoprite per dorare. Aggiungete acqua calda sul fondo se necessario."},{"q":"Perché il collo cotto rimane duro?","a":"La temperatura minima sicura non garantisce che il tessuto connettivo si sia ammorbidito. Proseguite dolcemente coperto; qui si cercano 80–85 °C e una consistenza tenera alla forchetta."}],"title":"Collo di maiale al forno succoso, coperto con alluminio","description":"Collo di maiale da 2 kg con senape, miele e aglio. Cottura coperta con alluminio, temperatura al cuore, riposo e salsa spiegati passo passo."}}},{"id":"2ed2de80-6968-4c88-8945-ad2388362669","language":"ja","public_path":"/ja/ポークボンディオーラのレシピ","recipe_group_id":"af4f77b1-24cd-4c6f-8d02-dbc92e3cfc24","expected_updated_at":"2026-10-21T13:48:02.819322+00:00","after":{"title":"ボンディオラのオーブン焼き｜アルミホイルでしっとり","notes":"<p>2kgの塊は160°Cで覆って約2時間焼いたところから柔らかさを確認します。厚みやオーブンで時間が変わるため、まだ硬ければ覆ったまま加熱を続け、天板の水分も確認してください。1kgでも時間が半分になるとは限りません。</p><p>ホイルは天板を覆って水分を保つために使い、肉をきつく包む必要はありません。最後に外して焼き色をつけ、はちみつを焦がさないよう見守ります。豚の塊肉の安全な最低中心温度は63°Cで、その後3分休ませます。このレシピでは柔らかさのため80〜85°Cを目安にし、フォークでも確認します。</p><p>15分休ませ、繊維を断つ方向に切ります。残りは焼き汁を加え、中心74°Cまで再加熱します。</p><h3>保存</h3><p>肉と肉汁はオーブンから出して2時間以内に、密閉容器に入れて冷蔵する。3～4日保存でき、ソースと一緒に74℃まで温め直す。小分けにして最大3か月冷凍できる。</p><p class='md-sources'>出典：<a href='https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart' rel='noopener' target='_blank'>USDA FSIS、安全な最低調理温度</a>、<a href='https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety' rel='noopener' target='_blank'>USDA FSIS、残り物と食品安全</a>（いずれも英語）。</p><p>出典: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>別の日に作りたい肉料理</h3><ul><li><a href=\"/ja/ビーフストロガノフクレープ\">ビーフストロガノフ風クレープ きのこ添え</a></li><li><a href=\"/ja/コロンビア風サンタロサノ生チョリソ\">サンタロサノ風チョリソの作り方｜自家製生ソーセージ</a></li></ul>","seo":{"faq":[{"q":"ボンディオラはどの部位ですか？","a":"脂が細かく入った豚の首の肉で、じっくり焼く調理に向きます。部位の呼び名は国によって異なります。"},{"q":"2kgの塊はどのくらい焼きますか？","a":"160°Cで覆って約2時間焼いたら確認します。硬ければ天板に水分を保ち、さらに加熱してください。厚みにも左右されます。最後に覆いを外し、200°Cで15〜20分焼き色をつけます。"},{"q":"アルミホイルはどう使いますか？","a":"天板を覆って蒸気を保ち、最後に外して焼き色をつけます。水分がなくなりそうなら天板に湯を足します。"},{"q":"火が通ったのに硬いのはなぜですか？","a":"安全な最低温度に達しても結合組織が柔らかいとは限りません。覆って穏やかに加熱を続け、80〜85°Cを目安にフォークでも確認します。"}],"title":"ボンディオラのオーブン焼き｜アルミホイルでしっとり","description":"豚の首肉2kgをマスタード、はちみつ、にんにくで味つけ。ホイルで覆う焼き方、中心温度、休ませ方、焼き汁のソースを解説します。"}}},{"id":"fd95af77-cc0c-47c1-8cda-4013e368b7cd","language":"pt","public_path":"/pt/bondiola-de-porco-assada-no-forno","recipe_group_id":"af4f77b1-24cd-4c6f-8d02-dbc92e3cfc24","expected_updated_at":"2026-10-25T04:48:08.371477+00:00","after":{"title":"Bondiola de porco no forno, suculenta no papel-alumínio","notes":"<p>Para uma peça de 2 kg, comece a verificar a maciez após cerca de 2 horas coberta a 160 °C. A espessura e o forno mudam o tempo: se continuar firme, asse coberta por mais tempo e mantenha líquido na assadeira. Uma peça de 1 kg não leva necessariamente metade do tempo.</p><p>Cubra a assadeira com papel-alumínio para reter umidade; não é preciso embrulhar a carne apertada. Descubra para dourar e vigie o mel. O mínimo seguro para uma peça inteira de porco é 63 °C com 3 minutos de descanso; aqui buscamos 80–85 °C para amaciar o corte, verificando também com um garfo.</p><p>Descanse 15 minutos e corte contra as fibras. Reaqueça as sobras com seus sucos até 74 °C no centro.</p><h3>Conservação</h3><p>Refrigere a carne e os sucos em até 2 horas depois de tirar do forno, em recipientes fechados. Dura de 3 a 4 dias e reaquece suavemente com um pouco do molho até 74 °C. Pode congelar em porções por até 3 meses.</p><p class='md-sources'>Fontes: <a href='https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart' rel='noopener' target='_blank'>USDA FSIS, temperaturas mínimas seguras</a>; <a href='https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety' rel='noopener' target='_blank'>USDA FSIS, sobras e segurança alimentar</a> (em inglês).</p><p>Fontes: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>Outras receitas de carne para variar</h3><ul><li><a href=\"/pt/panquecas-carne-stroganoff-cogumelos\">Panquecas de carne Stroganoff com cogumelos</a></li><li><a href=\"/pt/chourico-santarrosano-fresco\">Chouriço santarrosano caseiro: receita fresca</a></li></ul>","seo":{"faq":[{"q":"Que corte é a bondiola?","a":"É um corte do pescoço do porco com gordura entremeada, indicado para cocção lenta. O nome varia conforme o país."},{"q":"Quanto tempo leva uma peça de 2 kg?","a":"Verifique após cerca de 2 horas coberta a 160 °C. Continue se necessário com líquido na assadeira; a espessura também conta. Depois doure descoberta por 15–20 minutos a 200 °C."},{"q":"Como usar o papel-alumínio?","a":"Cubra a assadeira para reter vapor durante a cocção lenta e descubra para dourar. Se faltar líquido, acrescente água quente no fundo."},{"q":"Por que a carne cozida ainda está dura?","a":"A temperatura mínima segura não garante que o tecido conjuntivo tenha amaciado. Continue em fogo suave e coberta; aqui buscamos 80–85 °C e textura macia ao espetar com um garfo."}],"title":"Bondiola de porco no forno, suculenta no papel-alumínio","description":"Bondiola de 2 kg com mostarda, mel e alho. Assado coberto com papel-alumínio, temperatura interna, descanso e molho da assadeira passo a passo."}}},{"id":"6932000a-8c87-4626-bddd-f188f578a6bf","language":"de","public_path":"/de/chorizo-santarosano","recipe_group_id":"c27c68b3-375b-441e-83d3-0d87d44b3f44","expected_updated_at":"2026-10-21T13:48:02.819322+00:00","after":{"title":"Santarrosano-Chorizo selber machen: frische Wurst","summary":"Diese frische Santarrosano-Chorizo ist von Santa Rosa de Cabal in Kolumbien inspiriert. 800 g Schweineschulter und 200 g Schweinefett werden mit Frühlingszwiebel, Knoblauch und Kreuzkümmel zu 8 Würsten verarbeitet. Sie wird weder gepökelt noch luftgetrocknet.\n\nFleisch und Fett beim Verarbeiten kalt halten. Mischen, bis die Masse verbunden und leicht klebrig ist; wird sie warm, portionsweise arbeiten. Den Darm nicht zu straff füllen, damit er nicht platzt.\n\nEtwa 125 Minuten einschließlich 60 Minuten Kühlschrankruhe einplanen. Bei mittlerer bis kleiner Hitze bräunen und 71 °C im Kern prüfen. Die Außenfarbe zeigt den Gargrad nicht sicher an. Ohne Darm oder Wurstfüller Bratlinge formen.","notes":"<p>Rohes Fleisch nicht an der Luft trocknen. Masse und Würste kühl halten und innen auf 71 °C garen. Dies ist eine frische, nicht gereifte Hausversion.</p><p>Quellen: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>Weitere Fleischgerichte für den Speiseplan</h3><ul><li><a href=\"/de/kolumbianisches-lechona-rezept/\">Kolumbianische Lechona aus dem Ofen mit Reis und Erbsen</a></li><li><a href=\"/de/schweinefleisch-bondiola-rezept/\">Saftiger Schweinenacken aus dem Ofen, mit Alufolie</a></li></ul>","seo":{"faq":[{"a":"Nein. Frische Würste kühlen und am selben Tag garen oder roh einfrieren.","q":"Müssen sie einen Tag trocknen?"},{"a":"Ja, als Frikadellen formen und bis 71 °C Kerntemperatur garen.","q":"Ohne Darm möglich?"},{"q":"Welches Fleisch eignet sich?","a":"Hier werden 800 g Schweineschulter und 200 g Fett für 8 Stück verwendet. Grob zerkleinern und kalt halten; nur mageres Fleisch ergibt weniger Saftigkeit."},{"q":"Wie verhindere ich ein Platzen?","a":"Nicht überfüllen, bei mittlerer bis kleiner Hitze garen und mit einer Zange wenden. 71 °C im Kern messen statt wiederholt einzustechen."},{"q":"Was passt dazu?","a":"Heiß mit Arepa und Ají servieren. Vollständig gegarte Wurst eignet sich auch für ein eigenes Kichererbsengericht."}],"title":"Santarrosano-Chorizo selber machen: frische Wurst","description":"8 frische Santarrosano-Würste aus Schweinefleisch, Frühlingszwiebel, Knoblauch und Kreuzkümmel. Kalte Mischung, ohne Darm möglich, auf 71 °C garen.","image_variants":["/recetas/chorizo-santarosano/portada-1x1-v1.webp","/recetas/chorizo-santarosano/portada-4x3-v1.webp","/recetas/chorizo-santarosano/portada-16x9-v1.webp"]}}},{"id":"92051186-f001-41cd-9cc4-796e17fee733","language":"en","public_path":"/en/chorizo-santarosano","recipe_group_id":"c27c68b3-375b-441e-83d3-0d87d44b3f44","expected_updated_at":"2026-10-21T13:48:02.819322+00:00","after":{"title":"Homemade Santarrosano Chorizo: Fresh Colombian Sausage","summary":"This homemade Santarrosano chorizo is a fresh sausage inspired by Santa Rosa de Cabal, Colombia. It uses 800 g pork shoulder and 200 g pork fat, with spring onion, garlic and cumin, divided into 8 pieces. It is not cured or air-dried.\n\nKeep the meat and fat cold while preparing. Mix until combined and slightly sticky, working in batches if the mixture warms. Fill the casing without stretching it tightly so it is less likely to split.\n\nAllow about 125 minutes, including 60 minutes in the fridge. Brown over medium-low heat and check 71 °C (160 °F) in the center; exterior color does not confirm doneness. Without casings or a stuffer, shape patties from the same mixture.","notes":"<p>Do not air-dry raw meat. Keep mixture and links chilled, use cold tools and cook centers to 71°C (160°F). This is a fresh, uncured home adaptation.</p><p>References: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>More meat recipes for another meal</h3><ul><li><a href=\"/en/colombian-lechona-recipe/\">Colombian Lechona at Home: Pork, Rice and Peas</a></li><li><a href=\"/en/pork-bondiola-recipe/\">Juicy Oven-Roasted Pork Neck (Bondiola), Foil-Covered</a></li></ul>","seo":{"faq":[{"a":"No. These are fresh sausages: refrigerate and cook the same day or freeze raw links.","q":"Should the sausages dry for a day?"},{"a":"Shape patties from the same mix and cook centers to 71°C.","q":"What if I have no casing?"},{"q":"What meat is used for homemade Santarrosano chorizo?","a":"This recipe uses 800 g pork shoulder and 200 g pork fat for 8 pieces. Chop coarsely and keep everything cold; very lean meat changes the juiciness."},{"q":"How do I stop the casings splitting?","a":"Do not overfill; cook over medium-low heat and turn with tongs. Check 71 °C (160 °F) in the center with a thermometer rather than piercing repeatedly."},{"q":"What do you serve it with?","a":"Serve hot with arepa and ají. The fully cooked sausage also works in a separate chickpea and chorizo dish."}],"title":"Homemade Santarrosano Chorizo: Fresh Colombian Sausage","description":"Make 8 fresh Santarrosano-style pork sausages with spring onion, garlic and cumin. Cold mixing, a casing-free option and cooking to 71 °C (160 °F).","image_variants":["/recetas/chorizo-santarosano/portada-1x1-v1.webp","/recetas/chorizo-santarosano/portada-4x3-v1.webp","/recetas/chorizo-santarosano/portada-16x9-v1.webp"]}}},{"id":"93d53eaa-b516-4a91-994c-461f40899c7f","language":"es","public_path":"/chorizo-santarosano","recipe_group_id":"c27c68b3-375b-441e-83d3-0d87d44b3f44","expected_updated_at":"2026-10-12T07:47:12.552526+00:00","after":{"title":"Chorizo santarrosano casero: receta fresca paso a paso","summary":"Este chorizo santarrosano casero es una versión fresca inspirada en Santa Rosa de Cabal. La mezcla lleva 800 g de paleta de cerdo y 200 g de grasa, con cebolla larga, ajo y comino, y se divide en 8 piezas. No es un embutido curado ni se seca al aire.\n\nLa carne y la grasa deben permanecer frías durante la preparación. Mezcla hasta que los ingredientes se unan y la masa esté ligeramente pegajosa; trabaja por tandas si comienza a calentarse. Rellena la tripa sin tensarla demasiado para evitar que se abra.\n\nCalcula unos 125 minutos, incluidos 60 minutos de reposo en nevera. Dora a fuego medio bajo y comprueba 71 °C en el centro: el color exterior no confirma la cocción. Si no tienes tripa o embutidora, forma tortitas con la misma mezcla.","notes":"<p>No seques la carne al aire libre. Mantén la mezcla y los chorizos crudos refrigerados, trabaja con utensilios fríos y cocina el centro a 71 °C. Esta es una versión casera fresca, no curada.</p><p>Referencias: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>Otras recetas de carne para variar el menú</h3><ul><li><a href=\"/receta-de-lechona-colombiana/\">Lechona colombiana casera al horno, con arroz y arveja</a></li><li><a href=\"/receta-bondiola-de-cerdo/\">Bondiola de cerdo al horno jugosa, con papel aluminio</a></li></ul>","keywords":["chorizo santarrosano receta","chorizo colombiano casero","chorizo fresco","chorizo sin tripa","Santa Rosa de Cabal"],"seo":{"faq":[{"a":"No. Esta receta es de chorizo fresco: refrigera la mezcla y cocina el mismo día o congela las piezas crudas.","q":"¿Hay que secarlos un día?"},{"a":"Forma tortitas de la misma mezcla y cocina hasta 71 °C en el centro.","q":"¿Y si no tengo tripa?"},{"q":"¿Qué carne se usa para chorizo santarrosano casero?","a":"Esta formulación usa 800 g de paleta de cerdo y 200 g de grasa para 8 piezas. Pica grueso y mantén todo frío; usar solo carne muy magra cambia la jugosidad."},{"q":"¿Cómo evitar que el chorizo se abra al cocinarlo?","a":"No llenes demasiado la tripa y cocina a fuego medio bajo, girando con pinzas. Comprueba 71 °C en el centro con termómetro sin pinchar repetidamente."},{"q":"¿Con qué se acompaña?","a":"Sírvelo caliente con arepa y ají. También puedes preparar otra comida con esta mezcla cocida, como garbanzos con chorizo."}],"title":"Chorizo santarrosano casero: receta fresca paso a paso","description":"Cómo hacer 8 chorizos santarrosanos frescos con cerdo, cebolla larga, ajo y comino. Mezcla fría, opción sin tripa y cocción completa a 71 °C.","image_variants":["/recetas/chorizo-santarosano/portada-1x1-v1.webp","/recetas/chorizo-santarosano/portada-4x3-v1.webp","/recetas/chorizo-santarosano/portada-16x9-v1.webp"]}}},{"id":"bbe02232-6d43-43d9-b1fe-c4fba585a8e6","language":"fr","public_path":"/fr/chorizo-santarosano","recipe_group_id":"c27c68b3-375b-441e-83d3-0d87d44b3f44","expected_updated_at":"2026-10-21T13:48:02.819322+00:00","after":{"title":"Chorizo santarrosano maison : saucisse colombienne fraîche","summary":"Ce chorizo santarrosano maison est une saucisse fraîche inspirée de Santa Rosa de Cabal, en Colombie. Il associe 800 g d'épaule de porc et 200 g de gras, cébette, ail et cumin, répartis en 8 pièces. Il n'est ni affiné ni séché à l'air.\n\nGardez viande et gras froids. Mélangez jusqu'à obtenir une masse liée et légèrement collante ; travaillez par petites quantités si elle se réchauffe. Remplissez le boyau sans trop le tendre pour éviter qu'il éclate.\n\nComptez environ 125 minutes, dont 60 minutes au réfrigérateur. Dorez à feu moyen-doux et vérifiez 71 °C au centre : la couleur extérieure ne suffit pas. Sans boyau ni poussoir, façonnez des galettes.","notes":"<p>Ne pas sécher la viande crue à l’air libre. Garder farce et saucisses froides, et cuire le cœur à 71 °C. Version maison fraîche, non séchée.</p><p>Sources: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>D'autres recettes de viande pour varier</h3><ul><li><a href=\"/fr/recette-lechona-colombienne/\">Lechona colombienne maison au four, riz et pois</a></li><li><a href=\"/fr/recette-de-porc-bondiola/\">Échine de porc au four, juteuse et cuite sous aluminium</a></li></ul>","seo":{"faq":[{"a":"Non. Ce sont des saucisses fraîches à garder au froid, cuire le jour même ou congeler crues.","q":"Faut-il les sécher un jour ?"},{"a":"Former des galettes et cuire jusqu’à 71 °C au centre.","q":"Sans boyau ?"},{"q":"Quelle viande utiliser ?","a":"Cette recette utilise 800 g d'épaule et 200 g de gras de porc pour 8 pièces. Hachez gros et gardez froid ; une viande très maigre donne un résultat moins juteux."},{"q":"Comment éviter que le boyau éclate ?","a":"Ne le remplissez pas trop. Cuisez à feu moyen-doux en tournant avec une pince. Vérifiez 71 °C au centre au thermomètre sans piquer à répétition."},{"q":"Avec quoi le servir ?","a":"Servez chaud avec arepa et ají. La saucisse entièrement cuite convient aussi à un autre plat de pois chiches au chorizo."}],"title":"Chorizo santarrosano maison : saucisse colombienne fraîche","description":"Préparez 8 chorizos santarrosanos frais au porc, cébette, ail et cumin. Mélange froid, option sans boyau et cuisson à cœur à 71 °C.","image_variants":["/recetas/chorizo-santarosano/portada-1x1-v1.webp","/recetas/chorizo-santarosano/portada-4x3-v1.webp","/recetas/chorizo-santarosano/portada-16x9-v1.webp"]}}},{"id":"cd179b01-6c18-47dd-a4f3-6e79ac644158","language":"it","public_path":"/it/chorizo-santarosano","recipe_group_id":"c27c68b3-375b-441e-83d3-0d87d44b3f44","expected_updated_at":"2026-10-21T13:48:02.819322+00:00","after":{"title":"Chorizo santarrosano fatto in casa: salsiccia fresca","summary":"Questo chorizo santarrosano casalingo è una salsiccia fresca ispirata a Santa Rosa de Cabal, in Colombia. Unisce 800 g di spalla di maiale e 200 g di grasso con cipollotto, aglio e cumino, per 8 pezzi. Non è stagionato né essiccato all'aria.\n\nTenete carne e grasso freddi. Mescolate finché l'impasto è legato e leggermente appiccicoso; lavorate a porzioni se si scalda. Riempite il budello senza tenderlo troppo, per evitare rotture.\n\nCalcolate circa 125 minuti, inclusi 60 minuti in frigorifero. Dorate a fuoco medio-basso e controllate 71 °C al cuore: il colore esterno non basta. Senza budello o insaccatrice, formate delle polpette schiacciate.","notes":"<p>Non essiccare carne cruda all’aria. Tieni impasto e salsicce in frigo e cuoci il centro a 71 °C. Versione casalinga fresca, non stagionata.</p><p>Fonti: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>Altre ricette di carne per variare</h3><ul><li><a href=\"/it/ricetta-colombiana-lechona/\">Lechona colombiana al forno con riso e piselli</a></li><li><a href=\"/it/ricetta-maiale-bondiola/\">Collo di maiale al forno succoso, coperto con alluminio</a></li></ul>","seo":{"faq":[{"a":"No. Sono salsicce fresche: refrigera e cuoci il giorno stesso o congela crude.","q":"Devono asciugare un giorno?"},{"a":"Forma polpette schiacciate e cuoci fino a 71 °C al centro.","q":"Senza budello?"},{"q":"Quale carne si usa?","a":"Qui si usano 800 g di spalla e 200 g di grasso di maiale per 8 pezzi. Tritate grosso e tenete freddo; carne molto magra cambia la succosità."},{"q":"Come evitare che il budello si rompa?","a":"Non riempitelo troppo. Cuocete a fuoco medio-basso girando con pinze. Verificate 71 °C al cuore con termometro senza bucare ripetutamente."},{"q":"Con cosa si serve?","a":"Servite caldo con arepa e ají. La salsiccia completamente cotta si presta anche a un altro piatto di ceci e chorizo."}],"title":"Chorizo santarrosano fatto in casa: salsiccia fresca","description":"Preparate 8 chorizo santarrosano freschi con maiale, cipollotto, aglio e cumino. Impasto freddo, opzione senza budello e cottura a 71 °C al cuore.","image_variants":["/recetas/chorizo-santarosano/portada-1x1-v1.webp","/recetas/chorizo-santarosano/portada-4x3-v1.webp","/recetas/chorizo-santarosano/portada-16x9-v1.webp"]}}},{"id":"414a8fe4-8a6b-453a-a34c-6b22a496c242","language":"ja","public_path":"/ja/コロンビア風サンタロサノ生チョリソ","recipe_group_id":"c27c68b3-375b-441e-83d3-0d87d44b3f44","expected_updated_at":"2026-10-12T07:47:12.552526+00:00","after":{"title":"サンタロサノ風チョリソの作り方｜自家製生ソーセージ","summary":"コロンビアのサンタ・ロサ・デ・カバル風の、熟成させない自家製ソーセージです。豚肩肉800gと豚脂200gに、青ねぎ、にんにく、クミンを混ぜて8本に分けます。塩漬け熟成や風乾はしません。\n\n肉と脂は冷たい状態を保ちます。まとまりと軽い粘りが出るまで混ぜ、温まってきたら小分けに作業してください。腸は張りすぎないように詰め、破裂を防ぎます。\n\n冷蔵庫で60分休ませる時間を含め、所要時間は約125分です。中弱火で焼き、中心71°Cを温度計で確認します。表面の色だけでは判断できません。腸や詰め器がなければ、同じたねを平たいパティにします。","notes":"<p>生の肉を室温で干さない。具と腸詰めを冷蔵で保ち、中心温度71℃まで焼く。これは熟成させない家庭向けの生ソーセージ。</p><p>出典: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>別の日に作りたい肉料理</h3><ul><li><a href=\"/ja/コロンビアのレチョナレシピ/\">家庭で作るコロンビア風レチョナ｜豚肉・米・豆</a></li><li><a href=\"/ja/ポークボンディオーラのレシピ/\">ボンディオラのオーブン焼き｜アルミホイルでしっとり</a></li></ul>","seo":{"faq":[{"a":"いいえ。生ソーセージなので冷蔵し、その日のうちに焼くか生のまま冷凍します。","q":"一日干す必要がありますか？"},{"a":"平たいパティにし、中心71℃まで焼きます。","q":"腸がない場合は？"},{"q":"どの肉を使いますか？","a":"この配合は豚肩肉800gと豚脂200gで8本分です。粗くひき、冷たい状態を保ちます。赤身だけにすると仕上がりのジューシーさが変わります。"},{"q":"焼くときに腸が破れるのを防ぐには？","a":"詰めすぎず、中弱火で焼き、トングで返します。何度も穴を開けず、温度計で中心71°Cを確認してください。"},{"q":"何を添えますか？","a":"焼きたてにアレパとアヒを添えます。完全に加熱したチョリソは、別の料理としてひよこ豆と煮込むこともできます。"}],"title":"サンタロサノ風チョリソの作り方｜自家製生ソーセージ","description":"豚肉、青ねぎ、にんにく、クミンで作るサンタロサノ風チョリソ8本分。冷たいまま混ぜるコツ、腸なしの作り方、中心71°Cまでの加熱を解説。","image_variants":["/recetas/chorizo-santarosano/portada-1x1-v1.webp","/recetas/chorizo-santarosano/portada-4x3-v1.webp","/recetas/chorizo-santarosano/portada-16x9-v1.webp"]}}},{"id":"e23f4b43-bb28-45b6-b194-0f4731722765","language":"pt","public_path":"/pt/chourico-santarrosano-fresco","recipe_group_id":"c27c68b3-375b-441e-83d3-0d87d44b3f44","expected_updated_at":"2026-10-12T07:47:12.552526+00:00","after":{"title":"Chouriço santarrosano caseiro: receita fresca","summary":"Este chouriço santarrosano caseiro é uma versão fresca inspirada em Santa Rosa de Cabal, na Colômbia. Leva 800 g de paleta suína e 200 g de gordura, com cebolinha, alho e cominho, divididos em 8 peças. Não é curado nem seco ao ar.\n\nMantenha a carne e a gordura frias. Misture até dar liga e ficar levemente pegajoso; trabalhe em porções se aquecer. Recheie a tripa sem esticar demais para evitar rompimentos.\n\nReserve cerca de 125 minutos, incluindo 60 minutos na geladeira. Doure em fogo médio-baixo e confirme 71 °C no centro: a cor externa não basta. Sem tripa ou embutidora, modele discos com a mesma mistura.","notes":"<p>Não seque carne crua ao ar. Mantenha a mistura e os enchidos refrigerados e cozinhe o centro a 71 °C. Versão caseira fresca, não curada.</p><p>Fontes: <a href=\"https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures\">FoodSafety.gov</a>.</p><h3>Outras receitas de carne para variar</h3><ul><li><a href=\"/pt/receita-de-lechona-colombiana\">Lechona colombiana caseira no forno, com arroz e ervilha</a></li><li><a href=\"/pt/bondiola-de-porco-assada-no-forno\">Bondiola de porco no forno, suculenta no papel-alumínio</a></li></ul>","seo":{"faq":[{"a":"Não. São enchidos frescos: refrigere e cozinhe no próprio dia ou congele crus.","q":"Devem secar um dia?"},{"a":"Faça hambúrgueres e cozinhe até 71 °C no centro.","q":"Sem tripa?"},{"q":"Que carne usar?","a":"Esta receita usa 800 g de paleta e 200 g de gordura suína para 8 peças. Pique grosso e mantenha frio; só carne muito magra muda a suculência."},{"q":"Como evitar que a tripa estoure?","a":"Não recheie demais. Cozinhe em fogo médio-baixo, virando com pinça. Confira 71 °C no centro com termômetro sem furar repetidamente."},{"q":"Com o que servir?","a":"Sirva quente com arepa e ají. O chouriço totalmente cozido também combina com outro prato de grão-de-bico."}],"title":"Chouriço santarrosano caseiro: receita fresca","description":"Faça 8 chouriços santarrosanos frescos com porco, cebolinha, alho e cominho. Mistura fria, opção sem tripa e cocção completa a 71 °C no centro.","image_variants":["/recetas/chorizo-santarosano/portada-1x1-v1.webp","/recetas/chorizo-santarosano/portada-4x3-v1.webp","/recetas/chorizo-santarosano/portada-16x9-v1.webp"]}}},{"id":"3ef41826-103c-491f-9e9f-a3ad4d60d807","language":"de","public_path":"/de/kolumbianisches-lechona-rezept","recipe_group_id":"d0ad2da1-a1fa-4686-8c83-30303c1c005a","expected_updated_at":"2026-10-25T04:48:08.371477+00:00","after":{"title":"Kolumbianische Lechona aus dem Ofen mit Reis und Erbsen","summary":"Diese Lechona für zu Hause wird in einer tiefen Form mit Schweinefleisch, gelben Erbsen, Reis und Bauchfleisch mit Schwarte gebacken. Sie ergibt 8 Portionen ohne ein ganzes gefülltes Schwein. Es ist eine Variante mit Reis; die traditionelle Lechona aus Tolima enthält Schweinefleisch und Erbsen, keinen Reis.\n\nAm Vorabend beginnen: Erbsen einweichen und das marinierte Fleisch 8–12 Stunden kühlen. Am nächsten Tag Erbsen garen, Reis vorgaren und die Form füllen. Mit 12 Stunden nächtlicher Ruhe, Vorbereitung, Backen und abschließender Ruhezeit sind etwa 16 Stunden 20 Minuten einzuplanen.\n\nDie Schwarte trocken und ohne feuchte Marinade nach oben legen, die Füllung mit zurückbehaltener Kochflüssigkeit feucht halten. Eine tiefe Form mit Platz bis zum Rand verwenden und im Kern der Füllung 74 °C prüfen.","notes":"<h3>Tipps</h3><ul><li>Eine knusprige Schwarte braucht Trockenheit: nicht mit der Paste einreiben und unabgedeckt im Kühlschrank lagern.</li><li>Die Schulter in gleich große Stücke schneiden, damit sie gleichmäßig gart.</li><li>Die Füllung berührt beim Backen rohes Fleisch: Mit einem Thermometer prüfen, dass die Mitte mindestens 74 °C erreicht, bevor die Form aus dem Ofen kommt.</li><li>Den Reis nicht ganz durchgaren, bevor die Form geschichtet wird; in der Form würde er verkochen.</li></ul><h3>Alternativen</h3><ul><li>Schweineschmalz: Pflanzenöl geht auch, mit weniger Geschmack.</li><li>Bananenblätter: Die Form mit Backpapier auslegen und mit Alufolie abdecken; ein Teil des Aromas geht verloren.</li><li>Cebolla larga: Frühlingszwiebeln oder Lauchzwiebeln in gleicher Menge.</li><li>Achiote: edelsüßes Paprikapulver für die Farbe.</li><li>Schweinebauch ohne Schwarte: Das Rezept funktioniert, aber es gibt keine knusprige Schwarte.</li></ul><h3>Aufbewahrung</h3><p>Reste innerhalb von 2 Stunden abkühlen lassen und in geschlossenen Behältern in den Kühlschrank stellen. Sie halten sich 3 bis 4 Tage und werden erhitzt, bis die Mitte 74 °C erreicht. Portionen lassen sich bis zu 3 Monate einfrieren. Die Schwarte verliert beim Aufbewahren an Knusprigkeit: 10 Minuten bei 200 °C im Ofen bringt sie zurück.</p><p class=\"md-sources\">Quellen: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart\" rel=\"noopener\" target=\"_blank\">USDA FSIS, sichere Mindesttemperaturen</a>; <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety\" rel=\"noopener\" target=\"_blank\">USDA FSIS, Reste und Lebensmittelsicherheit</a> (beide auf Englisch).</p><p>Quellen: <a href=\"https://tolima.gov.co/noticias/442-lechona-tolimense-manjar-de-dioses-que-deleita-los-paladares-de-propios-y-visitantes-en-epocas-de-festividades-de-mitad-de-ano\">Gobernación del Tolima</a>.</p><h3>Weitere Fleischgerichte für den Speiseplan</h3><ul><li><a href=\"/de/chorizo-santarosano/\">Santarrosano-Chorizo selber machen: frische Wurst</a></li><li><a href=\"/de/schweinefleisch-bondiola-rezept/\">Saftiger Schweinenacken aus dem Ofen, mit Alufolie</a></li></ul>","seo":{"faq":[{"a":"Etwa 16 Stunden inklusive Ruhezeit: 8 bis 12 Stunden Marinade und Einweichen am Vorabend, rund 60 Minuten Vorbereitung und 3 Stunden im Ofen, dazu 20 Minuten Ruhe.","q":"Wie lange dauert Lechona zu Hause?"},{"a":"Ja. Marinade und Einweichen erledigen Sie am Vortag. Sie können die Lechona auch fertig backen, kühlen und bis zu 74 °C im Kern wieder erhitzen; die Schwarte wird 10 Minuten bei 200 °C wieder knusprig.","q":"Kann ich sie einen Tag vorher vorbereiten?"},{"a":"Nur zu drei Vierteln garen und die Füllung mit Erbsenkochwasser feucht mischen. Im Ofen nimmt der Reis den Fleischsaft auf und gart fertig.","q":"Wie verhindere ich, dass der Reis hart oder trocken wird?"},{"a":"Üblich sind Arepa und Ají. Ein frisch gepresster Spritzer Limette passt ebenfalls gut zum Fleisch.","q":"Was serviert man dazu?"},{"q":"Ist dies die traditionelle Lechona aus Tolima ohne Reis?","a":"Nein. Dies ist eine Ofenvariante mit Reis. Die traditionelle Tolima-Lechona besteht aus Schweinefleisch und Erbsen ohne Reis. Zum Weglassen müssten Mengen und Flüssigkeit angepasst werden."},{"q":"Für wie viele Personen reicht das Rezept?","a":"Für 8 Portionen. Eine tiefe Form nicht bis zum Rand füllen. Eine doppelte Menge auf zwei Formen verteilen und beide mit Thermometer prüfen; die Garzeit verdoppelt sich nicht automatisch."}],"title":"Kolumbianische Lechona aus dem Ofen mit Reis und Erbsen","description":"Lechona für 8 Personen mit Schweinefleisch, Reis, Erbsen und knuspriger Schwarte. Vorbereitung am Vortag und Unterschied zur Variante aus Tolima."}}},{"id":"14f903dc-f571-42fc-8885-516c7625e79f","language":"en","public_path":"/en/colombian-lechona-recipe","recipe_group_id":"d0ad2da1-a1fa-4686-8c83-30303c1c005a","expected_updated_at":"2026-10-21T13:49:01.992102+00:00","after":{"title":"Colombian Lechona at Home: Pork, Rice and Peas","summary":"This home-style Colombian lechona is baked in a deep dish with pork, yellow peas, rice and skin-on pork belly. It serves 8 without stuffing a whole pig. It is a rice-based adaptation: traditional Tolima lechona contains pork and peas, without rice.\n\nStart the night before: soak the peas and refrigerate the marinated pork for 8–12 hours. The next day, cook the peas, partially cook the rice and assemble the dish. Allow roughly 16 hours 20 minutes overall when counting a 12-hour overnight rest, preparation, baking and final resting.\n\nKeep the skin facing up, dry and free of wet marinade, and moisten the filling with the reserved cooking liquid. Use a deep dish with headroom and check that the center of the filling reaches 74 °C (165 °F) before serving.","notes":"<h3>Tips</h3><ul><li>Crisp skin depends on dryness: do not coat it with the paste, and leave it uncovered in the fridge.</li><li>Cut the shoulder into similar-sized pieces so it cooks evenly.</li><li>The filling touches raw meat while baking: use a thermometer and confirm at least 74 °C (165 °F) in the center before taking it out.</li><li>Do not cook the rice fully before assembling; it would overcook in the dish.</li></ul><h3>Substitutions</h3><ul><li>Lard: vegetable oil works, with less flavor.</li><li>Banana leaves: line the dish with parchment and cover with foil; some aroma is lost.</li><li>Cebolla larga: scallions or spring onions, in the same amount.</li><li>Achiote: sweet paprika, for color.</li><li>Pork belly without skin: the recipe works, but there will be no crackling.</li></ul><h3>Storage</h3><p>Cool leftovers and refrigerate them within 2 hours, in closed containers. They keep for 3 to 4 days and should be reheated until the center reaches 74 °C (165 °F). You can freeze portions for up to 3 months. The skin loses its crunch in storage: revive it for 10 minutes in a 200 °C (400 °F) oven.</p><p class=\"md-sources\">Sources: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart\" rel=\"noopener\" target=\"_blank\">USDA FSIS, safe minimum internal temperatures</a>; <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety\" rel=\"noopener\" target=\"_blank\">USDA FSIS, leftovers and food safety</a>.</p><p>References: <a href=\"https://tolima.gov.co/noticias/442-lechona-tolimense-manjar-de-dioses-que-deleita-los-paladares-de-propios-y-visitantes-en-epocas-de-festividades-de-mitad-de-ano\">Gobernación del Tolima</a>.</p><h3>More meat recipes for another meal</h3><ul><li><a href=\"/en/chorizo-santarosano/\">Homemade Santarrosano Chorizo: Fresh Colombian Sausage</a></li><li><a href=\"/en/pork-bondiola-recipe/\">Juicy Oven-Roasted Pork Neck (Bondiola), Foil-Covered</a></li></ul>","seo":{"faq":[{"a":"About 16 hours including resting: 8 to 12 hours of marinating and soaking the night before, about 60 minutes of prep and 3 hours in the oven, plus 20 minutes of rest.","q":"How long does lechona take to make at home?"},{"a":"Yes. The marinade and the soaking are done the day before. You can also bake it fully, refrigerate it and reheat it until the center reaches 74 °C (165 °F), reviving the skin for 10 minutes at 200 °C (400 °F).","q":"Can I prepare it a day ahead?"},{"a":"Cook it only to three-quarters and mix the filling with pea cooking liquid so it stays moist. In the oven it absorbs the pork juices and finishes cooking.","q":"How do I keep the rice from turning hard or dry?"},{"a":"Arepa and ají are the usual companions. A squeeze of fresh lime also works well with the pork.","q":"What do you serve with lechona?"},{"q":"Is this traditional rice-free Tolima lechona?","a":"No. This is a home-oven adaptation with rice. Traditional Tolima lechona uses pork and peas without rice. Simply removing the rice would require adjusting quantities and liquid."},{"q":"How many people does it serve?","a":"It makes 8 servings. Use a deep dish with room at the top. For a double batch, divide between two dishes and check each with a thermometer; cooking time does not automatically double."}],"title":"Colombian Lechona at Home: Pork, Rice and Peas","description":"Make Colombian lechona for 8 with pork, rice, peas and crisp skin in a home oven. Plan the night before and learn how it differs from Tolima's version."}}},{"id":"ee2a6f49-dc58-4795-85cf-de08ca595056","language":"es","public_path":"/receta-de-lechona-colombiana","recipe_group_id":"d0ad2da1-a1fa-4686-8c83-30303c1c005a","expected_updated_at":"2026-10-12T07:44:38.783604+00:00","after":{"title":"Lechona colombiana casera al horno, con arroz y arveja","summary":"Esta lechona colombiana se prepara en una fuente de horno con cerdo, arveja amarilla, arroz y panceta con piel. Rinde 8 porciones y evita tener que rellenar un cerdo entero. Es una adaptación casera con arroz: la lechona tolimense tradicional lleva cerdo y arveja, sin arroz.\n\nOrganiza el trabajo desde la víspera: remoja las arvejas y deja el cerdo adobado en la nevera de 8 a 12 horas. Al día siguiente, cuece las arvejas, deja el arroz parcialmente cocido y monta la fuente. El tiempo total orientativo es de 16 horas y 20 minutos, contando 12 horas de reposo, preparación, horno y reposo final.\n\nLa piel debe quedar arriba, seca y sin adobo húmedo; el relleno se mantiene húmedo con el caldo reservado. Usa una fuente honda en la que quepa todo sin llegar al borde y comprueba 74 °C en el centro del relleno antes de servir.","notes":"<h3>Consejos</h3><ul><li>La piel crujiente depende de que esté seca: no la adobes con la pasta y déjala sin tapar en la nevera.</li><li>Corta la paleta en trozos de tamaño parecido para que se cueza por igual.</li><li>El relleno toca la carne cruda durante el horneado: usa un termómetro y confirma al menos 74 °C en el centro antes de sacarla.</li><li>No cuezas el arroz por completo antes de montar; se pasaría de cocción dentro de la fuente.</li></ul><h3>Sustituciones</h3><ul><li>Manteca de cerdo: puedes usar aceite vegetal, con menos sabor.</li><li>Hojas de plátano: forra con papel de horno y cubre con aluminio; se pierde parte del aroma.</li><li>Cebolla larga: cebolleta o cebollín, en la misma cantidad.</li><li>Color o achiote: pimentón dulce, para dar tono.</li><li>Panceta sin piel: la receta funciona, pero no habrá piel crujiente.</li></ul><h3>Conservación</h3><p>Enfría las sobras y llévalas a la nevera en un plazo de 2 horas, en recipientes cerrados. Se conservan de 3 a 4 días y se recalientan hasta que el centro alcance 74 °C. Puedes congelar porciones hasta 3 meses. La piel pierde crujiente al guardarla: recupérala 10 minutos en horno a 200 °C.</p><p class=\"md-sources\">Fuentes: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart\" rel=\"noopener\" target=\"_blank\">USDA FSIS, temperaturas mínimas seguras</a>; <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety\" rel=\"noopener\" target=\"_blank\">USDA FSIS, sobras y seguridad alimentaria</a> (ambas en inglés).</p><p>Referencias: <a href=\"https://tolima.gov.co/noticias/442-lechona-tolimense-manjar-de-dioses-que-deleita-los-paladares-de-propios-y-visitantes-en-epocas-de-festividades-de-mitad-de-ano\">Gobernación del Tolima</a>.</p><h3>Otras recetas de carne para variar el menú</h3><ul><li><a href=\"/chorizo-santarosano/\">Chorizo santarrosano casero: receta fresca paso a paso</a></li><li><a href=\"/receta-bondiola-de-cerdo/\">Bondiola de cerdo al horno jugosa, con papel aluminio</a></li></ul>","keywords":["lechona colombiana","lechona casera al horno","lechona con arroz","lechona para 8 personas","cerdo con arveja","lechona tolimense sin arroz diferencia"],"seo":{"faq":[{"a":"Unas 16 horas contando el reposo: 8 a 12 horas de adobo y remojo la noche anterior, unos 60 minutos de preparación y 3 horas de horno, más 20 minutos de reposo.","q":"¿Cuánto tiempo lleva hacer lechona en casa?"},{"a":"Sí. El adobo y el remojo se hacen el día anterior. También puedes hornearla entera, refrigerarla y recalentarla hasta 74 °C en el centro, recuperando la piel 10 minutos a 200 °C.","q":"¿Puedo dejarla lista con un día de antelación?"},{"a":"Cuécelo solo hasta tres cuartos y mezcla el relleno con caldo de las arvejas para que quede húmedo. Dentro del horno absorbe los jugos del cerdo y termina de cocerse.","q":"¿Cómo evito que el arroz quede duro o seco?"},{"a":"Lo habitual es servirla con arepa y ají. Un limón recién exprimido también va muy bien con la carne.","q":"¿Con qué se sirve la lechona?"},{"q":"¿Esta es una lechona tolimense sin arroz?","a":"No. Es una adaptación casera al horno con arroz. La lechona tolimense tradicional se prepara con carne de cerdo y arveja, sin arroz. Quitar el arroz de esta formulación exige ajustar cantidades y líquido."},{"q":"¿Para cuántas personas alcanza esta receta?","a":"Rinde 8 porciones. Usa una fuente honda con espacio libre en el borde. Si duplicas cantidades, reparte en dos fuentes y comprueba cada una con termómetro; el tiempo no se duplica automáticamente."}],"title":"Lechona colombiana casera al horno, con arroz y arveja","description":"Lechona colombiana casera para 8: cerdo, arroz, arveja y piel crujiente en horno doméstico. Preparación desde la víspera y diferencia con la tolimense."}}},{"id":"fc5a6964-3139-436b-951f-413f08431c74","language":"fr","public_path":"/fr/recette-lechona-colombienne","recipe_group_id":"d0ad2da1-a1fa-4686-8c83-30303c1c005a","expected_updated_at":"2026-10-21T13:49:01.992102+00:00","after":{"title":"Lechona colombienne maison au four, riz et pois","summary":"Cette lechona maison cuit dans un plat profond avec porc, pois jaunes, riz et poitrine avec couenne. Elle donne 8 portions sans farcir un cochon entier. C'est une adaptation avec riz ; la lechona traditionnelle du Tolima associe porc et pois, sans riz.\n\nCommencez la veille : faites tremper les pois et marinez le porc au réfrigérateur 8 à 12 heures. Le lendemain, cuisez les pois, précuisez le riz et montez le plat. Comptez environ 16 h 20 au total avec 12 heures de repos nocturne, préparation, four et repos final.\n\nPlacez la couenne sèche vers le haut, sans marinade humide, et gardez la farce moelleuse avec le bouillon réservé. Choisissez un plat profond sans le remplir à ras bord et vérifiez 74 °C au centre de la farce.","notes":"<h3>Conseils</h3><ul><li>Une couenne croustillante dépend de sa sécheresse : ne l'enduisez pas de pâte et laissez-la à découvert au réfrigérateur.</li><li>Coupez l'épaule en morceaux de taille similaire pour une cuisson homogène.</li><li>La farce touche de la viande crue pendant la cuisson : utilisez un thermomètre et vérifiez au moins 74 °C au centre avant de sortir le plat.</li><li>Ne cuisez pas le riz entièrement avant le montage ; il serait trop cuit dans le plat.</li></ul><h3>Substitutions</h3><ul><li>Saindoux : l'huile végétale convient, avec moins de goût.</li><li>Feuilles de bananier : tapissez le plat de papier sulfurisé et couvrez d'aluminium ; une partie de l'arôme se perd.</li><li>Cebolla larga : oignons verts ou ciboule, en même quantité.</li><li>Achiote : paprika doux, pour la couleur.</li><li>Poitrine sans couenne : la recette fonctionne, mais sans couenne croustillante.</li></ul><h3>Conservation</h3><p>Laissez refroidir les restes et placez-les au réfrigérateur dans les 2 heures, en récipients fermés. Ils se gardent 3 à 4 jours et se réchauffent jusqu'à ce que le centre atteigne 74 °C. Vous pouvez congeler des portions jusqu'à 3 mois. La couenne perd son croquant : redonnez-le-lui 10 minutes dans un four à 200 °C.</p><p class=\"md-sources\">Sources : <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart\" rel=\"noopener\" target=\"_blank\">USDA FSIS, températures internes minimales sûres</a> ; <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety\" rel=\"noopener\" target=\"_blank\">USDA FSIS, restes et sécurité alimentaire</a> (en anglais).</p><p>Sources: <a href=\"https://tolima.gov.co/noticias/442-lechona-tolimense-manjar-de-dioses-que-deleita-los-paladares-de-propios-y-visitantes-en-epocas-de-festividades-de-mitad-de-ano\">Gobernación del Tolima</a>.</p><h3>D'autres recettes de viande pour varier</h3><ul><li><a href=\"/fr/chorizo-santarosano/\">Chorizo santarrosano maison : saucisse colombienne fraîche</a></li><li><a href=\"/fr/recette-de-porc-bondiola/\">Échine de porc au four, juteuse et cuite sous aluminium</a></li></ul>","seo":{"faq":[{"a":"Environ 16 heures avec les temps de repos : 8 à 12 heures de marinade et de trempage la veille, environ 60 minutes de préparation et 3 heures de four, plus 20 minutes de repos.","q":"Combien de temps faut-il pour préparer une lechona à la maison ?"},{"a":"Oui. La marinade et le trempage se font la veille. Vous pouvez aussi la cuire entièrement, la réfrigérer et la réchauffer jusqu'à 74 °C au centre, en redonnant du croquant à la couenne 10 minutes à 200 °C.","q":"Puis-je la préparer la veille ?"},{"a":"Cuisez-le seulement aux trois quarts et mélangez la farce avec la cuisson des pois pour qu'elle reste humide. Au four, il absorbe le jus du porc et termine sa cuisson.","q":"Comment éviter que le riz soit dur ou sec ?"},{"a":"On la sert habituellement avec une arepa et de l'ají. Un filet de citron vert frais accompagne aussi très bien la viande.","q":"Avec quoi sert-on la lechona ?"},{"q":"Est-ce la lechona traditionnelle du Tolima sans riz ?","a":"Non. C'est une adaptation au four avec riz. La lechona traditionnelle du Tolima contient porc et pois, sans riz. Supprimer le riz demanderait d'ajuster les quantités et le liquide."},{"q":"Combien de personnes sert cette recette ?","a":"Elle donne 8 portions. Utilisez un plat profond avec de la place en haut. Pour doubler, répartissez dans deux plats et contrôlez chacun au thermomètre ; le temps ne double pas automatiquement."}],"title":"Lechona colombienne maison au four, riz et pois","description":"Lechona pour 8 au four domestique : porc, riz, pois et couenne croustillante. Préparation la veille et différence avec la version du Tolima."}}},{"id":"01d4efd2-b894-4d98-aba6-d8eefc5d9b49","language":"it","public_path":"/it/ricetta-colombiana-lechona","recipe_group_id":"d0ad2da1-a1fa-4686-8c83-30303c1c005a","expected_updated_at":"2026-10-21T13:49:01.992102+00:00","after":{"title":"Lechona colombiana al forno con riso e piselli","summary":"Questa lechona casalinga cuoce in una teglia alta con maiale, piselli gialli, riso e pancetta con cotenna. Dà 8 porzioni senza farcire un maiale intero. È un adattamento con riso; la lechona tradizionale del Tolima contiene maiale e piselli, senza riso.\n\nIniziate la sera prima: ammollate i piselli e marinate il maiale in frigorifero 8–12 ore. Il giorno dopo cuocete i piselli, precuocete il riso e assemblate la teglia. Con 12 ore di riposo notturno, preparazione, forno e riposo finale, calcolate circa 16 ore e 20 minuti complessivi.\n\nTenete la cotenna asciutta verso l'alto, senza marinata umida, e il ripieno umido con il brodo tenuto da parte. Usate una teglia alta senza colmarla e controllate 74 °C al centro del ripieno.","notes":"<h3>Consigli</h3><ul><li>Una cotenna croccante dipende dall'asciuttezza: non spalmatela con la pasta e lasciatela scoperta in frigorifero.</li><li>Tagliate la spalla in pezzi di dimensioni simili per una cottura uniforme.</li><li>Il ripieno tocca la carne cruda durante la cottura: usate un termometro e verificate almeno 74 °C al centro prima di sfornare.</li><li>Non cuocete il riso del tutto prima di assemblare; in teglia scuocerebbe.</li></ul><h3>Sostituzioni</h3><ul><li>Strutto: va bene l'olio vegetale, con meno sapore.</li><li>Foglie di banano: foderate con carta forno e coprite con alluminio; si perde parte dell'aroma.</li><li>Cebolla larga: cipollotti o cipolline fresche, nella stessa quantità.</li><li>Achiote: paprika dolce, per il colore.</li><li>Pancetta senza cotenna: la ricetta funziona, ma non avrete la cotenna croccante.</li></ul><h3>Conservazione</h3><p>Fate raffreddare gli avanzi e metteteli in frigorifero entro 2 ore, in contenitori chiusi. Si conservano da 3 a 4 giorni e si riscaldano finché il centro raggiunge 74 °C. Potete congelare le porzioni fino a 3 mesi. La cotenna perde croccantezza: recuperatela 10 minuti in forno a 200 °C.</p><p class=\"md-sources\">Fonti: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart\" rel=\"noopener\" target=\"_blank\">USDA FSIS, temperature interne minime sicure</a>; <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety\" rel=\"noopener\" target=\"_blank\">USDA FSIS, avanzi e sicurezza alimentare</a> (in inglese).</p><p>Fonti: <a href=\"https://tolima.gov.co/noticias/442-lechona-tolimense-manjar-de-dioses-que-deleita-los-paladares-de-propios-y-visitantes-en-epocas-de-festividades-de-mitad-de-ano\">Gobernación del Tolima</a>.</p><h3>Altre ricette di carne per variare</h3><ul><li><a href=\"/it/chorizo-santarosano/\">Chorizo santarrosano fatto in casa: salsiccia fresca</a></li><li><a href=\"/it/ricetta-maiale-bondiola/\">Collo di maiale al forno succoso, coperto con alluminio</a></li></ul>","seo":{"faq":[{"a":"Circa 16 ore con i tempi di riposo: da 8 a 12 ore di marinata e ammollo la sera prima, circa 60 minuti di preparazione e 3 ore di forno, più 20 minuti di riposo.","q":"Quanto tempo ci vuole per fare la lechona a casa?"},{"a":"Sì. Marinata e ammollo si fanno il giorno prima. Potete anche cuocerla interamente, refrigerarla e riscaldarla fino a 74 °C al centro, recuperando la cotenna 10 minuti a 200 °C.","q":"Posso prepararla il giorno prima?"},{"a":"Cuocetelo solo a tre quarti e mescolate il ripieno con l'acqua di cottura dei piselli perché resti umido. In forno assorbe il sugo del maiale e finisce di cuocere.","q":"Come evito che il riso venga duro o secco?"},{"a":"Di solito con arepa e ají. Anche una spruzzata di lime fresco si abbina bene alla carne.","q":"Con cosa si serve la lechona?"},{"q":"È la lechona tradizionale del Tolima senza riso?","a":"No. È un adattamento al forno con riso. La lechona tradizionale del Tolima usa maiale e piselli senza riso. Per togliere il riso occorre rivedere quantità e liquido."},{"q":"Per quante persone è la ricetta?","a":"Per 8 porzioni. Usate una teglia alta con margine libero. Per raddoppiare dividete in due teglie e controllate ciascuna con termometro; il tempo non raddoppia automaticamente."}],"title":"Lechona colombiana al forno con riso e piselli","description":"Lechona per 8 nel forno di casa: maiale, riso, piselli e cotenna croccante. Preparazione dalla sera prima e differenza dalla versione del Tolima."}}},{"id":"7f839942-3dca-4d16-842b-a3b01b2425cb","language":"ja","public_path":"/ja/コロンビアのレチョナレシピ","recipe_group_id":"d0ad2da1-a1fa-4686-8c83-30303c1c005a","expected_updated_at":"2026-10-21T13:49:01.992102+00:00","after":{"title":"家庭で作るコロンビア風レチョナ｜豚肉・米・豆","summary":"深い耐熱皿に豚肉、黄えんどう豆、米、皮付き豚バラ肉を重ねて焼く家庭向けレチョナです。豚を丸ごと使わずに8人分作れます。米を使うアレンジで、伝統的なトリマ地方のレチョナは豚肉と豆を使い、米は入れません。\n\n前夜に豆を浸水させ、味つけした豚肉を冷蔵庫で8〜12時間休ませます。翌日、豆をゆで、米に途中まで火を通して皿に詰めます。前夜の休ませ時間を12時間とした場合、下ごしらえ、焼き時間、最後の休ませ時間を含む目安は合計16時間20分です。\n\n皮は上向きにして乾かし、湿ったマリネ液をつけないようにします。中身には取り分けたゆで汁を加えます。縁まで詰めず余裕のある深皿を使い、詰め物の中心が74°Cになったことを確認してください。","notes":"<h3>ポイント</h3><ul><li>パリッとした皮は乾燥が決め手です。ペーストは塗らず、冷蔵庫でふたをせずに置きます。</li><li>肩肉は大きさをそろえて切ると、均一に火が通ります。</li><li>詰め物は焼く間に生の肉に触れます。取り出す前に温度計で中心が74°C以上あることを確認してください。</li><li>組み立てる前に米を完全に炊かないでください。皿の中で炊きすぎになります。</li></ul><h3>代用</h3><ul><li>ラード：植物油でも作れますが、風味は少し軽くなります。</li><li>バナナの葉：オーブンシートを敷いてアルミホイルで覆います。香りは少し弱くなります。</li><li>セボージャ・ラルガ：青ねぎや万能ねぎを同量で。</li><li>アチオテ：色づけにスイートパプリカパウダーを。</li><li>皮なしのバラ肉：作れますが、パリパリの皮はできません。</li></ul><h3>保存</h3><p>残りは2時間以内に冷まして、密閉容器で冷蔵します。3〜4日保存でき、食べる前に中心が74°Cになるまで再加熱します。1食分ずつ、3か月まで冷凍できます。皮は保存するとパリパリ感が落ちるので、200°Cのオーブンで10分温めると戻ります。</p><p class=\"md-sources\">出典：<a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart\" rel=\"noopener\" target=\"_blank\">USDA FSIS「安全な最低内部温度」</a>、<a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety\" rel=\"noopener\" target=\"_blank\">USDA FSIS「残り物と食品の安全」</a>（いずれも英語）。</p><p>出典: <a href=\"https://tolima.gov.co/noticias/442-lechona-tolimense-manjar-de-dioses-que-deleita-los-paladares-de-propios-y-visitantes-en-epocas-de-festividades-de-mitad-de-ano\">Gobernación del Tolima</a>.</p><h3>別の日に作りたい肉料理</h3><ul><li><a href=\"/ja/コロンビア風サンタロサノ生チョリソ\">サンタロサノ風チョリソの作り方｜自家製生ソーセージ</a></li><li><a href=\"/ja/ポークボンディオーラのレシピ/\">ボンディオラのオーブン焼き｜アルミホイルでしっとり</a></li></ul>","seo":{"faq":[{"a":"休ませる時間を含めておよそ16時間です。前の晩に8〜12時間のマリネと豆の浸水、当日は下ごしらえ約60分、オーブン3時間、そして20分の休ませ時間です。","q":"家でレチョナを作るのにどのくらい時間がかかりますか？"},{"a":"はい。マリネと豆の浸水は前日に行います。完全に焼いて冷蔵し、中心が74°Cになるまで再加熱することもできます。皮は200°Cで10分温めると、またパリッとします。","q":"前日に準備できますか？"},{"a":"米は7〜8割までにとどめ、詰め物は豆のゆで汁でしっとり混ぜます。オーブンの中で豚肉の汁を吸って仕上がります。","q":"米が固くなったりパサついたりしないためには？"},{"a":"アレパとアヒ（唐辛子ソース）が定番です。フレッシュなライムを絞っても、肉によく合います。","q":"何を添えて食べますか？"},{"q":"米を入れない伝統的なトリマ地方のレチョナですか？","a":"いいえ。これは米を入れて家庭のオーブンで作るアレンジです。伝統的なトリマ地方のレチョナは豚肉と豆を使い、米は入れません。この配合から米だけを抜く場合は、分量と水分の調整が必要です。"},{"q":"何人分作れますか？","a":"8人分です。深い耐熱皿を使い、縁に余裕を残します。倍量は2皿に分け、それぞれの中心温度を確認してください。加熱時間が自動的に倍になるわけではありません。"}],"title":"家庭で作るコロンビア風レチョナ｜豚肉・米・豆","description":"豚肉、米、黄えんどう豆、パリッとした皮で作る8人分のレチョナ。前夜の準備から家庭のオーブンでの焼き方、トリマ地方の料理との違いまで。"}}},{"id":"ca89d1d0-682a-4c9b-ab02-a273afe20a90","language":"pt","public_path":"/pt/receita-de-lechona-colombiana","recipe_group_id":"d0ad2da1-a1fa-4686-8c83-30303c1c005a","expected_updated_at":"2026-10-04T18:01:39.168611+00:00","after":{"title":"Lechona colombiana caseira no forno, com arroz e ervilha","summary":"Esta lechona caseira vai ao forno numa travessa funda com porco, ervilha amarela, arroz e barriga com couro. Rende 8 porções sem rechear um porco inteiro. É uma adaptação com arroz; a lechona tradicional de Tolima leva porco e ervilha, sem arroz.\n\nComece na véspera: deixe a ervilha de molho e marine o porco na geladeira por 8–12 horas. No dia seguinte, cozinhe a ervilha, pré-cozinhe o arroz e monte a travessa. Contando 12 horas de descanso noturno, preparo, forno e descanso final, reserve cerca de 16 horas e 20 minutos no total.\n\nMantenha o couro seco virado para cima, sem tempero úmido, e o recheio úmido com o caldo reservado. Use travessa funda sem encher até a borda e verifique 74 °C no centro do recheio.","notes":"<h3>Dicas</h3><ul><li>O couro crocante depende de estar seco: não passe a pasta nele e deixe a barriga descoberta na geladeira.</li><li>Corte a paleta em pedaços de tamanho parecido para cozinhar por igual.</li><li>O recheio encosta na carne crua durante o assado: use um termômetro e confirme pelo menos 74 °C no centro antes de tirar do forno.</li><li>Não cozinhe o arroz por completo antes de montar; ele passaria do ponto na travessa.</li></ul><h3>Substituições</h3><ul><li>Banha de porco: óleo vegetal serve, com menos sabor.</li><li>Folhas de bananeira: forre com papel manteiga e cubra com papel-alumínio; perde-se parte do aroma.</li><li>Cebolinha-verde: cebolinha comum, na mesma quantidade.</li><li>Urucum: páprica doce, para dar cor.</li><li>Barriga sem couro: a receita funciona, mas não terá couro crocante.</li></ul><h3>Conservação</h3><p>Deixe as sobras esfriarem e leve à geladeira em até 2 horas, em recipientes fechados. Duram de 3 a 4 dias e devem ser reaquecidas até o centro chegar a 74 °C. Você pode congelar porções por até 3 meses. O couro perde a crocância ao guardar: recupere-o por 10 minutos no forno a 200 °C.</p><p class=\"md-sources\">Fontes: <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/safe-temperature-chart\" rel=\"noopener\" target=\"_blank\">USDA FSIS, temperaturas internas mínimas seguras</a>; <a href=\"https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation/food-safety-basics/leftovers-and-food-safety\" rel=\"noopener\" target=\"_blank\">USDA FSIS, sobras e segurança dos alimentos</a> (ambas em inglês).</p><p>Fontes: <a href=\"https://tolima.gov.co/noticias/442-lechona-tolimense-manjar-de-dioses-que-deleita-los-paladares-de-propios-y-visitantes-en-epocas-de-festividades-de-mitad-de-ano\">Gobernación del Tolima</a>.</p><h3>Outras receitas de carne para variar</h3><ul><li><a href=\"/pt/chourico-santarrosano-fresco\">Chouriço santarrosano caseiro: receita fresca</a></li><li><a href=\"/pt/bondiola-de-porco-assada-no-forno\">Bondiola de porco no forno, suculenta no papel-alumínio</a></li></ul>","seo":{"faq":[{"a":"Cerca de 16 horas contando o descanso: 8 a 12 horas de tempero e de molho na véspera, uns 60 minutos de preparo e 3 horas de forno, mais 20 minutos de descanso.","q":"Quanto tempo leva para fazer lechona em casa?"},{"a":"Sim. O tempero e o molho se fazem na véspera. Você também pode assar por completo, refrigerar e reaquecer até o centro chegar a 74 °C, recuperando o couro por 10 minutos a 200 °C.","q":"Posso deixar pronta de um dia para o outro?"},{"a":"Cozinhe só até três quartos e misture o recheio com o caldo da ervilha para ficar úmido. No forno ele absorve o caldo do porco e termina de cozinhar.","q":"Como evitar que o arroz fique duro ou seco?"},{"a":"O comum é servir com arepa e ají. Um fio de limão espremido na hora também combina muito bem com a carne.","q":"Com o que se serve a lechona?"},{"q":"É a lechona tradicional de Tolima sem arroz?","a":"Não. É uma adaptação ao forno com arroz. A lechona tradicional de Tolima leva porco e ervilha, sem arroz. Retirar o arroz desta formulação exige ajustar quantidades e líquido."},{"q":"Para quantas pessoas rende?","a":"Rende 8 porções. Use travessa funda com espaço na borda. Para dobrar, divida em duas travessas e confira cada uma com termômetro; o tempo não dobra automaticamente."}],"title":"Lechona colombiana caseira no forno, com arroz e ervilha","description":"Lechona para 8 no forno de casa: porco, arroz, ervilha e couro crocante. Preparo na véspera e diferença em relação à versão de Tolima."}}}]$payload$::jsonb; x jsonb; v public.recipes; n integer:=0;
BEGIN
 IF jsonb_array_length(payload)<>28 THEN RAISE EXCEPTION 'Expected 28 existing recipes'; END IF;
 PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
 IF NOT public.is_admin() THEN RAISE EXCEPTION 'Missing admin context'; END IF;
 -- Lock and validate the whole batch before any write.
 FOR x IN SELECT value FROM jsonb_array_elements(payload) LOOP
  SELECT * INTO STRICT v FROM public.recipes WHERE id=(x->>'id')::uuid FOR UPDATE;
  IF NOT v.published OR v.language IS DISTINCT FROM x->>'language' OR v.public_path IS DISTINCT FROM x->>'public_path' OR v.recipe_group_id IS DISTINCT FROM (x->>'recipe_group_id')::uuid OR v.updated_at IS DISTINCT FROM (x->>'expected_updated_at')::timestamptz THEN RAISE EXCEPTION 'Concurrent edit or identity mismatch: %',v.public_path; END IF;
 END LOOP;
 FOR x IN SELECT value FROM jsonb_array_elements(payload) LOOP
  SELECT * INTO STRICT v FROM public.recipes WHERE id=(x->>'id')::uuid;
  -- The basic update RPC has no arguments for these editorial JSONB/text fields.
  UPDATE public.recipes SET summary=coalesce(x->'after'->>'summary',v.summary),notes=x->'after'->>'notes',seo=x->'after'->'seo',keywords=CASE WHEN x->'after' ? 'keywords' THEN ARRAY(SELECT jsonb_array_elements_text(x->'after'->'keywords')) ELSE v.keywords END,total_time_minutes=coalesce((x->'after'->>'total_time_minutes')::int,v.total_time_minutes) WHERE id=v.id;
  PERFORM public.update_recipe(v.id,v.slug,coalesce(x->'after'->>'title',v.title),coalesce(x->'after'->>'excerpt',v.excerpt),v.ingredients,coalesce(x->'after'->'steps',v.steps),v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,v.published);
  n:=n+1;
 END LOOP;
 IF n<>28 THEN RAISE EXCEPTION 'Unexpected update count'; END IF;
END $refuerzo$;
SELECT language,count(*) AS reinforced FROM public.recipes WHERE id IN (SELECT (value->>'id')::uuid FROM jsonb_array_elements($payload$[{"id":"900a29cc-a46f-4dc4-bd44-6515cbab06f4"},{"id":"9708424f-7580-4e3f-930a-3e16cbfec6ba"},{"id":"8358b894-382b-4032-a693-2b57df99bb3f"},{"id":"9dbfe294-f3eb-4c6c-a450-a1a4aee60013"},{"id":"b87caa7d-eb4f-49b8-823a-aa89835e7e99"},{"id":"00631fec-7127-4bec-9379-872c56a2acfc"},{"id":"fd9286e6-bae7-4889-9558-7e34ff073824"},{"id":"702bee80-233d-4477-b545-f5e66bb647ad"},{"id":"b705a6a3-ad43-4226-b8c5-6ff08f9b849e"},{"id":"067c8e64-4822-4ea8-945d-be7193b40a95"},{"id":"09c2ab9b-2c60-4099-9eb2-1c4d06b74a0b"},{"id":"73b7a347-1fc2-4a23-a6f6-974400575731"},{"id":"2ed2de80-6968-4c88-8945-ad2388362669"},{"id":"fd95af77-cc0c-47c1-8cda-4013e368b7cd"},{"id":"6932000a-8c87-4626-bddd-f188f578a6bf"},{"id":"92051186-f001-41cd-9cc4-796e17fee733"},{"id":"93d53eaa-b516-4a91-994c-461f40899c7f"},{"id":"bbe02232-6d43-43d9-b1fe-c4fba585a8e6"},{"id":"cd179b01-6c18-47dd-a4f3-6e79ac644158"},{"id":"414a8fe4-8a6b-453a-a34c-6b22a496c242"},{"id":"e23f4b43-bb28-45b6-b194-0f4731722765"},{"id":"3ef41826-103c-491f-9e9f-a3ad4d60d807"},{"id":"14f903dc-f571-42fc-8885-516c7625e79f"},{"id":"ee2a6f49-dc58-4795-85cf-de08ca595056"},{"id":"fc5a6964-3139-436b-951f-413f08431c74"},{"id":"01d4efd2-b894-4d98-aba6-d8eefc5d9b49"},{"id":"7f839942-3dca-4d16-842b-a3b01b2425cb"},{"id":"ca89d1d0-682a-4c9b-ab02-a273afe20a90"}]$payload$::jsonb)) GROUP BY language ORDER BY language;
